(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["fr"] = {"ui":{"lead":"On n’a pas seulement joué aux jeux : on les a peints. Agrandissez 3 300 ans de peintures et de figures pour en voir les détails.","details":"Détails","links":"Voir ou jouer au jeu","record":"À propos de l’œuvre","game":"Jeu","exhibit":"Collection","room":"Salle","room_chance":"Hasard","hint":"Pincez ou utilisez la molette pour zoomer · glissez pour déplacer · touchez un numéro","r_artist":"Artiste","r_date":"Date","r_place":"Lieu","r_medium":"Technique","r_size":"Dimensions","r_museum":"Musée","r_credit":"Provenance","r_rights":"Image","met":"The Metropolitan Museum of Art","cc0":"Accès libre (domaine public)","metlink":"L’œuvre sur le site du musée","credit":"Images : The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago et le Rijksmuseum, accès libre (domaine public).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"La reine Néfertari jouant au senet","artist":"Nina de Garis Davies (fac-similé)","date":"original v. 1290–1224 av. J.-C. · fac-similé 1921–22","place":"Égypte (Vallée des Reines)","game":"Senet","medium":"Tempera sur papier (fac-similé à mi-grandeur)","p":["Néfertari était la grande épouse royale de Ramsès II. Voici la copie d’une peinture de sa tombe, dans la Vallée des Reines, faite dans la tombe même en 1921–22 ; les fissures et les lacunes du mur ont été copiées elles aussi.","Assise devant un plateau, la reine joue au senet contre un adversaire invisible. Peint dans une tombe, le jeu signifiait sans doute plus qu’un divertissement : gagner le voyage vers l’au-delà."],"spots":[["Deux sortes de pions","Des pions pointus et des pions en forme de bobine se dressent sur le plateau : un jeu pour chaque joueur."],["La main de la reine","Ses doigts s’apprêtent à prendre un pion."],["Plateau et support","Le plateau est vu de profil : on n’en voit pas les cases. Il repose sur un support aux pieds fins."],["Son nom","Le nom de la reine est inscrit dans un ovale, un cartouche."],["L’adversaire invisible","Personne en face : la reine joue contre un adversaire qu’on ne voit pas."]]},"hydria":{"title":"Achille et Ajax jouant à un jeu de plateau (hydrie)","artist":"Attribuée au groupe de Léagros","date":"v. 510 av. J.-C.","place":"Grèce (Attique)","game":"Un jeu de dés","medium":"Terre cuite (figures noires)","p":["Pendant le siège de Troie, deux héros grecs, Achille et Ajax, tuent le temps autour d’un plateau. La scène a été inventée vers 540 av. J.-C. par le potier et peintre Exékias ; son original est conservé sur une amphore des musées du Vatican.","Le sujet a été très prisé entre 540 et 480 av. J.-C. environ : on en connaît plus de 150 exemples. Sur cette hydrie, la déesse Athéna se tient au centre. Les héros jouent à un jeu où les pions avancent selon le jet des dés."],"spots":[["Athéna","La déesse Athéna se tient entre les deux héros."],["Le héros de gauche","Sa lance toujours en main, il se penche sur le plateau."],["Le héros de droite","Lui non plus n’a pas posé ses armes : un moment de jeu en pleine guerre."],["Le plateau","Le bloc bas entre eux est le plateau."],["L’épaule","Sur l’épaule du vase, un char s’élance."]]},"liubo":{"title":"Deux figures assises jouant au liubo","date":"Ier siècle av. J.-C. – Ier siècle apr. J.-C.","place":"Chine (dynastie Han)","game":"Liubo","medium":"Terre cuite peinte","p":["Deux joueurs de liubo, le jeu à la mode de la Chine des Han. On plaçait de telles figures dans les tombes, avec le vœu que les plaisirs de la vie continuent après la mort.","Sur la photo, le plateau de liubo et les pions en os de la collection de ce musée sont posés entre eux. Les figures saisissent un moment dramatique d’une partie acharnée."],"spots":[["Le plateau de liubo","Le même plateau que « Plateau et pièces de liubo » de la collection : voyez les marques en T, L et V."],["Le joueur de gauche","Il étudie le plateau avec calme."],["Le joueur de droite","La main levée, la bouche grande ouverte : vient-il de jouer le coup gagnant ?"],["Pions sur le plateau","Des pions en os se dressent aux deux bouts du plateau."],["Pions hors du plateau","D’autres pions sont posés au sol."]]},"shahnama":{"title":"« Bozorgmehr résout le jeu indien des échecs », du Shâhnâmeh de Shâh Tahmâsp","artist":"Peinture attribuée à ʿAbd al-Vahhab","date":"v. 1530–35","place":"Iran (Tabriz)","game":"Échecs","medium":"Aquarelle opaque, encre, argent et or sur papier","p":["Une scène de l’épopée de Ferdowsi, le Shâhnâmeh (Livre des rois). Le roi de l’Inde envoie un émissaire avec un échiquier et ses pièces et défie le roi perse Nushirvan : qu’il découvre comment se joue le jeu, et l’Inde paiera tribut.","Seul le jeune sage Bozorgmehr le résout à temps. Selon le Shâhnâmeh, la Perse envoie ensuite le backgammon en retour, et les Indiens ne parviennent pas à le résoudre. Le roi et ses courtisans fixent le plateau et les joueurs."],"spots":[["L’échiquier","Les pièces se dressent sur un plateau quadrillé, si petites qu’on en distingue mal les formes."],["Le roi Nushirvan","Sur son trône, il attend de voir l’énigme résolue."],["Autour du plateau","Les joueurs se penchent sur l’échiquier."],["Les vers","Les cartouches du haut et du bas portent des vers de Ferdowsi."],["Les courtisans","Des hommes coiffés de turbans à hautes baguettes rouges regardent, debout."]]},"chaupar":{"title":"Shiva et Parvati jouant au chaupar, d’une série du Rasamanjari","artist":"Devidasa de Nurpur","date":"1694–95","place":"Inde (Basohli, Jammu)","game":"Chaupar (parent de l’ancêtre du Ludo)","medium":"Aquarelle opaque, encre, argent et or sur papier","p":["Une page d’une série illustrant le Rasamanjari, poème d’amour sanskrit du XVe siècle. Le dieu Shiva et son épouse Parvati sont assis sur une peau de tigre autour d’un plateau en forme de croix.","Shiva vient de soutirer un collier à Parvati en trichant, et elle le supplie. Couleurs hardies, profondeur incertaine de l’espace, couleur et geste porteurs de sens : ce sont les marques de l’école de Basohli."],"spots":[["Le plateau en croix","Le chaupar et le pachisi se jouent sur un plateau en forme de croix comme celui-ci."],["Barres blanches sur le plateau","Sans doute les dés longs (pasa) du chaupar."],["Shiva","Le corps blanc, un serpent autour du cou."],["Parvati","La main tendue, elle réclame son collier."],["La peau de tigre","Tous deux sont assis sur une peau de tigre."]]},"shogi":{"title":"Jeune femme et jeune homme jouant au shōgi (« Chūnagon Kanesuke », des Trente-six poètes immortels)","artist":"Suzuki Harunobu","date":"v. 1767–69","place":"Japon (Edo)","game":"Shogi","medium":"Estampe gravée sur bois (nishiki-e)","p":["Une estampe d’une série évoquant les Trente-six poètes immortels ; celle-ci figure le poète Chūnagon Kanesuke. Un soir d’été, près d’une moustiquaire, une jeune femme et un jeune homme sont penchés sur un shogiban.","Harunobu est l’artiste qui a popularisé l’estampe en couleurs, imprimée avec de nombreuses planches. Même les pièces sur le plateau sont dessinées en détail."],"spots":[["Un shogiban sur pieds","Un plateau épais sur pieds, comme ceux d’aujourd’hui."],["Une petite boîte","Sans doute la boîte des pièces."],["La moustiquaire","Une moustiquaire verte est tendue : c’est un soir d’été."],["La lanterne","Une lampe sur pied éclaire le plateau."],["Le poème","Le cartouche en forme de nuage porte le nom du poète et un poème."]]},"sugoroku":{"title":"Deux jeunes femmes jouant au sugoroku","artist":"Utagawa Toyokuni I","date":"époque d’Edo (fin du XVIIIe – début du XIXe s.)","place":"Japon (Edo)","game":"Ban-sugoroku (parent du backgammon)","medium":"Diptyque d’estampes gravées sur bois","p":["Deux estampes réunies en une large image : des jeunes femmes rassemblées dans une pièce jouent au ban-sugoroku. Ce jeu est un parent du backgammon, de la même lignée que le plateau de sugoroku du Shōsōin de cette collection.","Des pions blancs et noirs sont posés sur le plateau, et la jeune femme de droite tient un cornet pour agiter les dés. Le mont Fuji apparaît par la fenêtre."],"spots":[["Le plateau","Pions blancs et noirs sur ses longues flèches."],["Le cornet","On y agite les dés."],["Pions hors du plateau","Déjà sortis, ou pas encore entrés ?"],["Le mont Fuji","Le Fuji derrière la fenêtre."],["La jonction","Ici se rejoignent les deux estampes."]]},"eakins":{"title":"Les Joueurs d’échecs","artist":"Thomas Eakins","date":"1876","place":"États-Unis (Philadelphie)","game":"Échecs","medium":"Huile sur bois","p":["Dans le salon d’une maison de Philadelphie, deux amis jouent aux échecs sous le regard du père de l’artiste, Benjamin Eakins. Eakins tenait sa construction soignée de l’espace et la précision de ses détails de son maître parisien, Gérôme.","En 1881, Les Joueurs d’échecs devient la première œuvre acceptée par le Metropolitan Museum en don d’un artiste vivant."],"spots":[["Les pièces","Dans la pièce sombre, les pièces de l’échiquier ressortent dans la lumière."],["Le père de l’artiste","Debout, il suit la partie : Benjamin Eakins."],["Le joueur de droite","Le peintre George W. Holmes, ami du père de l’artiste."],["Le tiroir","Une inscription latine : « Le fils de Benjamin Eakins a peint ceci en 76. »"],["Au-dessus de la cheminée","Une reproduction d’un tableau de Gérôme, le maître d’Eakins."],["Le chat","Par terre, seul le chat semble se désintéresser de la partie."]]},"weiqi":{"title":"Plat aux immortels jouant au weiqi","artist":"Anonyme","date":"1425–1436 (dynastie Ming, ère Xuande)","place":"Chine","game":"Go (weiqi)","medium":"Laque sculptée rouge et verte","size":"H. 3,5 ; l. 14,9 ; L. 23,5 cm","credit":"Don de Florence et Herbert Irving, 2015","p":["Un plat en laque sculptée : des dizaines de couches ont été posées puis taillées, avec une couche verte sous la rouge, si bien que la profondeur de la taille fait apparaître les couleurs. Dans le bord polylobé, des immortels jouent au go sous un pin.","La Chine connaît la légende de Lanke, le « manche de hache pourri » : le bûcheron Wang Zhi regarda des immortels jouer au go dans la montagne et, revenu à lui, découvrit qu’il s’était écoulé tant de temps que le manche de sa hache avait pourri. Les immortels au goban étaient un sujet apprécié. Les sources ne disent pas qui est le personnage debout."],"spots":[["Le goban","Le goban entre les deux immortels, sculpté jusque dans ses lignes."],["Les immortels jouant","Deux personnages assis près des rochers, autour du plateau."],["Le personnage debout","Un personnage debout, un peu à l’écart. Il rappelle le bûcheron de la légende, mais on ignore qui il est."],["La lune","Une lune ronde dans le ciel (ou peut-être le soleil)."],["Le pin","Un pin aux branches étalées, arbre qui évoque souvent la longévité et le pays des immortels."],["Le bord aux pivoines","De grandes pivoines et leurs feuilles sont sculptées sur le bord."]]},"webb":{"title":"Les joueurs de backgammon (cabinet)","artist":"Philip Webb (dessin), Edward Burne-Jones (peinture), Morris, Marshall, Faulkner & Co. (fabrication)","date":"1861","place":"Grande-Bretagne (Londres)","game":"Backgammon","medium":"Pin peint, huile sur cuir, laiton, cuivre","size":"H. 185,4 ; l. 114,3 ; p. 53,3 cm","credit":"Rogers Fund, 1926","p":["L’un des tout premiers meubles de la firme que William Morris fonda avec des amis en 1861. Sur le cuir des portes, un homme et une femme vêtus à la mode médiévale jouent au backgammon, peints à l’huile. Il fut présenté à l’Exposition internationale de Londres en 1862.","Il résume l’ambition Arts and Crafts d’effacer la frontière entre beaux-arts et arts appliqués. Le fond de cuir est poinçonné de minuscules points, une technique médiévale."],"spots":[["Le plateau","Le plateau de backgammon sur la table, entre eux."],["L’homme","Un jeune homme, un pion à la main, observe le plateau."],["La femme","Face à lui, une femme tient un pion (ou un cornet à dés)."],["Les fleurs à leurs pieds","Des fleurs poussent aux pieds des joueurs."],["Le cuir poinçonné","Le fond de cuir est poinçonné de points fins qui accrochent la lumière."],["Les bandes de losanges","Des bandes de losanges sur fond d’or encadrent les portes en haut et en bas."]]},"liberale":{"title":"Les Joueurs d’échecs","artist":"Liberale da Verona","date":"vers 1475","place":"Italie (Vérone)","game":"Échecs","medium":"Tempera sur bois","size":"34,9 × 41,3 cm","credit":"Collection Maitland F. Griggs, legs de Maitland F. Griggs, 1943","p":["Fragment de la façade d’un cassone, le coffre peint qui contenait le trousseau d’une mariée dans l’Italie de la Renaissance. Liberale était aussi connu pour avoir enluminé les livres de chœur de la cathédrale de Sienne.","On y voit un moment d’une histoire d’amour non identifiée. Sur le fragment jumeau, une jeune fille à une fenêtre semble inviter un jeune homme à entrer ; ici, tous deux jouent aux échecs. Selon le musée, elle est sur le point de perdre. Les échecs étaient une image favorite de la séduction dans la littérature amoureuse de l’époque."],"spots":[["L’échiquier","Un échiquier rouge et blanc garni de pièces sombres ; la partie semble toucher à sa fin."],["Le jeune homme","Il tend la main vers l’échiquier et semble près de gagner."],["La jeune fille","Assise en face ; sur le panneau jumeau, elle l’appelle d’une fenêtre."],["La fenêtre","Derrière la fenêtre ouverte, une colline et le ciel."],["Jeunes gens qui regardent","Des hommes aux bras croisés suivent la partie."],["Jeunes femmes qui regardent","Des femmes observent la partie derrière la colonne."]]},"mirror":{"title":"Valve de miroir : couple jouant aux échecs","artist":"Anonyme","date":"1325-1350","place":"France (Paris)","game":"Échecs","medium":"Ivoire","size":"Diamètre 10,2 cm","credit":"Achat sur le fonds J. H. Wade, 1940","p":["Ce disque d’ivoire grand comme la paume couvrait un miroir de poche. Dans le Paris du XIVe siècle, un miroir de métal poli était serré entre deux plaques d’ivoire et emporté partout ; ces ivoires sculptés étaient des objets de luxe prisés de la cour et de l’aristocratie.","Sous une tente aux rideaux relevés, un jeune homme et une dame jouent aux échecs. Dans les romans médiévaux, les échecs figuraient à la fois l’amour et la guerre. On a proposé d’y voir Tristan et Iseut, ou Lancelot et Guenièvre, mais nul ne le sait. Le musée pose la question à ses visiteurs : qui, selon vous, est en train de gagner ?"],"spots":[["L’échiquier","Un échiquier sur une table à pied unique, garni de quelques pièces."],["Le jeune homme","Il tend la main pour jouer son coup."],["La dame","Une femme coiffée d’un voile ; ses doigts touchent une pièce."],["La main fermée","Son autre main, fermée, repose sur ses genoux. Tient-elle une pièce prise ?"],["La tente","Des rideaux noués de chaque côté, décor fréquent des scènes d’échecs sur les valves de miroir."]]},"morris":{"title":"Un tablier de jeu (la marelle)","artist":"Peter Flötner","date":"1500-1546","place":"Allemagne","game":"Jeu du moulin (marelle)","medium":"Gravure sur bois","credit":"Fonds de dotation Charles W. Harkness, 1923","p":["Une gravure sur bois de Peter Flötner, l’un des sculpteurs les plus doués de la Nuremberg de la Renaissance, qui dessina aussi des ornements, des meubles, des modèles d’orfèvrerie et un jeu de cartes célèbre pour sa satire. Sous les rinceaux se cache le tablier du jeu du moulin, ou marelle (« Mühle » en allemand) : trois carrés emboîtés reliés au milieu de chaque côté.","Le tablier compte 24 points. Aligner trois de ses pions (un moulin) permet d’en retirer un à l’adversaire. Ces gravures servaient aussi de modèles aux artisans, et le musée a montré cette feuille dans une exposition de modèles et de dessins d’orfèvres. On ignore si l’on jouait sur le papier ou si on le recopiait dans le bois ou le métal."],"spots":[["Le carré central","Le carré le plus intérieur, couvert d’entrelacs fins."],["Un coin extérieur","Coin du carré extérieur : l’un des 24 points où se posent les pions."],["Un coin du milieu","Les coins du carré médian sont aussi des points."],["Les lignes de jonction","Des bandes relient les trois carrés au milieu de chaque côté ; les pions s’y déplacent aussi."],["Un mascaron","Cartouches enroulés et visages en haut, en bas et sur les côtés : ornement grotesque de la Renaissance."],["La bordure de vigne","Feuilles et fruits taillés en blanc sur fond noir."]]},"leifeng":{"title":"Jeu de plateau de la pagode Leifeng","artist":"Anonyme","date":"1736-1795 (ère Qianlong)","place":"Chine","game":"Jeu de parcours","medium":"Gravure sur bois ; encre sur papier","size":"31 × 29,8 cm","credit":"Achat sur le fonds J. H. Wade, 2025","p":["Une feuille imprimée faite pour jouer, du règne de l’empereur Qianlong de la Chine des Qing. Ses cases rassemblent les personnages de la Légende du Serpent blanc : l’esprit serpent Bai Suzhen (la « Dame blanche »), sa compagne Xiaoqing (la « Petite Verte »), le jeune Xu Xuan (Xu Xian dans les versions plus tardives) et le moine Fahai, qui finit par enfermer la Dame blanche sous la pagode Leifeng, au bord du lac de l’Ouest.","Le parcours tourne en spirale depuis une case marquée 起馬, « départ », jusqu’à la pagode du centre. On courait sans doute à travers l’histoire avec des dés, comme au jeu de l’oie occidental ; les règles ne sont pas conservées. Selon le musée, ces estampes en couleurs se vendaient en ville et s’accrochaient aux murs, dans la culture visuelle urbaine — chaque couleur imprimée avec sa propre planche gravée."],"spots":[["Départ","La case marquée 起馬, « départ » : sans doute le point de départ."],["La Dame blanche et la Petite Verte","L’esprit serpent Bai Suzhen et sa compagne Xiaoqing."],["Xu Xuan","Le jeune homme qui épouse la Dame blanche."],["Le moine Fahai","Le moine qui l’enferme sous la pagode."],["La pagode Leifeng","La pagode du lac de l’Ouest à Hangzhou, où finit l’histoire."],["Le centre","Une femme assise devant la pagode et un homme agenouillé : la dernière scène du récit, et peut-être l’arrivée."]]},"tutinama":{"title":"Le singe blessé mord la main du prince, son partenaire d’échecs (d’un Tuti-nama, Contes d’un perroquet)","artist":"Dasavanta","date":"vers 1560","place":"Inde (cour moghole d’Akbar)","game":"Échecs","medium":"Tempera, encre et or sur papier","size":"20 × 14,2 cm (peinture 10,2 × 10,6 cm)","credit":"Don de Mme A. Dean Perry, 1962","p":["Une illustration du Tuti-nama, les « Contes d’un perroquet », réalisé à la cour de l’empereur moghol Akbar. C’est l’une des histoires qu’une mère perroquet raconte à ses petits pour les détourner des amitiés avec d’autres espèces, comme les renardeaux. Un singe habile aux échecs jouait souvent avec un prince.","Un jour, devant des invités, le singe fit une plaisanterie blessante ; le prince le gifla, et le singe lui mordit la main. Dehors, à droite, des serviteurs préparent le repas sous les yeux des invités stupéfaits. Une inscription en bas nomme Dasavanta, qui deviendra l’un des maîtres les plus célèbres de la cour moghole ; jeune, il posa une couche de bleu froid sous sa peinture."],"spots":[["Le singe","Il mord la main du prince, son partenaire aux échecs."],["Le prince","Le prince mordu."],["L’échiquier","Un échiquier à cases rouges posé au sol."],["Les invités stupéfaits","Les invités de la réception."],["Le repas","Dehors, des serviteurs mettent des marmites sur le feu."],["Le texte persan","En haut, l’histoire écrite en persan."]]},"teniers":{"title":"Partie de trictrac","artist":"David Teniers","date":"années 1640","place":"Flandres","game":"Backgammon","medium":"Huile sur bois, transposée sur toile","size":"59 × 80,6 cm","credit":"Don de M. et Mme Samuel D. Wise, 1943","p":["Une partie de backgammon à gros enjeu, peinte par le Flamand Teniers. Le jeu est très ancien : sa forme moderne apparaît au XVe siècle, et le nom « backgammon » naît à peu près à l’époque de ce tableau. Au XVIIe siècle, il était très en vogue et se jouait souvent pour de l’argent.","Des badauds entourent les deux joueurs, et contre le mur quelqu’un tient la marque. D’après les femmes qui regardent — l’une se penche à une fenêtre —, le musée voit ici la salle de jeu d’une maison close. Ces scènes de jeu portaient souvent une morale : le jeu d’argent était sot, voire coupable, et une perte de temps."],"spots":[["Le tablier","Un tablier de backgammon ouvert sur la table, la partie en cours."],["L’homme en blanc","Un joueur vu de dos, qui avance la main vers ses dames."],["L’homme pensif","Son adversaire, la joue dans la main."],["La marque","Un homme marque une planchette au mur : les points, ou les mises ?"],["La femme à la fenêtre","Une femme âgée qui regarde d’en haut."],["L’arrière-salle","Au fond, des hommes boivent près d’une jeune femme."]]},"imari":{"title":"Plat à deux joueurs de go","artist":"Anonyme","date":"XVIIIe siècle","place":"Japon (époque d’Edo)","game":"Go","medium":"Porcelaine moulée, émaux sur couverte (Hizen, style Imari)","size":"2,4 × 13,8 cm","credit":"Collection Severance et Greta Millikin, 1964","p":["Sur ce petit plat carré, deux hommes jouent au go sous un pin : l’un, en jaune, assis face au goban posé à même le sol ; son adversaire, en vert, adossé à l’arbre.","C’est une porcelaine d’Imari faite dans le Hizen (aujourd’hui Saga et Nagasaki), dont les verts rappellent les émaux de Kutani. Elle fut faite pour l’exportation, quand le Japon avait remplacé la Chine comme principal fournisseur de porcelaine de l’Europe."],"spots":[["Le goban","Un plateau quadrillé posé à même le sol."],["L’homme en jaune","Assis face au plateau."],["L’homme en vert","Son adversaire, adossé à l’arbre, souriant."],["Le pin","Un pin étend ses branches au-dessus d’eux."],["Le cadre rouge","Un cadre rouge à pans coupés entoure la scène."]]},"shoei":{"title":"Les Quatre Arts (l’un d’une paire de paravents)","artist":"attribué à Kanō Shōei","date":"fin du XVIe–début du XVIIe siècle","place":"Japon (époque Momoyama)","game":"Go","medium":"L’un d’une paire de paravents à six feuilles ; encre et couleurs légères sur papier","size":"153 × 358,6 cm","credit":"Fonds John L. Severance, 1979","p":["Un paravent à six feuilles attribué à Kanō Shōei, de l’école Kanō. Avec son pendant, il montre les « Quatre Arts » attendus d’un lettré chinois : jouer du qin, jouer au qi (go), la calligraphie et la peinture. Ici, des gentilshommes chinois et leurs serviteurs se délassent dans la campagne, sous les pins.","Au centre, deux hommes jouent au go tandis qu’un troisième regarde. Tout près, une table porte des livres et un qin encore dans son étui de tissu, qui attend qu’on en joue. La scène équilibre plaisir et bienséance. Le musée relève qu’un des serviteurs est distrait par le mouvement d’un poisson dans l’eau."],"spots":[["Le goban","Un plateau sur pieds ; deux gentilshommes jouent face à face."],["Les gentilshommes","Deux joueurs et un troisième qui regarde."],["La table","Sans doute la table aux livres et au qin dans son étui."],["Les serviteurs","Des serviteurs qui attendent près de la table."],["Le serviteur distrait","Allongé au bord de l’eau, il regarde un poisson."],["Le pin","Un grand pin étend ses branches au-dessus de la scène."]]},"umaya":{"title":"Paravent des écuries (go et shogi sur la véranda)","artist":"Anonyme","date":"Début du XVIe siècle","place":"Japon (époque Muromachi)","game":"Go et shogi","medium":"L’un d’une paire de paravents à six feuilles ; encre, couleurs et or sur papier","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Ce paravent de six feuilles assemblées forme une paire avec un autre. Les chevaux de prix dans leurs stalles en sont peut-être le sujet principal, mais il se passe beaucoup de choses sur la véranda, au premier plan.","On s’y affronte à deux jeux différents : le go à gauche, le shogi à droite. Selon le musée, la vivacité de la scène naît du jeu entre les chevaux agités et la stratégie tranquille des parties. Au Japon, on pensait que les singes protégeaient les chevaux, et l’on en gardait parfois dans les écuries."],"spots":[["Le goban","Un plateau finement quadrillé, avec des pierres noires."],["Deux hommes en bonnet noir","Des hommes coiffés du haut eboshi noir : celui en vert tend la main vers le plateau, celui en rouge regarde."],["Le plateau de shogi","De grandes cases, bien moins nombreuses que sur le goban."],["L’adversaire hilare","Un moine au crâne rasé saisit une pièce tandis que l’homme en face se tient la tête en riant aux éclats. Quelqu’un vient-il de marquer un point ?"],["Un singe","Au bout de la véranda, un singe en veste rouge ?"],["Un cheval","Un cheval noir se cabre, retenu par ses cordes."]]},"goryeo":{"title":"Aiguière à décor incrusté de joueurs de go","artist":"Anonyme","date":"XIIIe siècle","place":"Corée (dynastie Goryeo)","game":"Go (baduk)","medium":"Céladon à décor incrusté d’engobes blanc et noir","size":"H. 20,4 cm, diam. 14,3 cm","credit":"Don de John L. Severance, 1917","p":["Une aiguière en céladon de Goryeo, avec bec et anse. L’incrustation — graver des traits dans l’argile, les remplir d’engobe blanc et noir, puis émailler et cuire — était la spécialité des potiers de Goryeo ; ici, dans un médaillon, deux personnages assis sous un saule se détachent en blanc.","Entre eux se trouve un plateau, et le musée rapproche la scène des images de parties de go — baduk en coréen. Jouer de la cithare, du go, pratiquer la calligraphie et la peinture formaient les « quatre arts » du lettré, dont les élégantes réunions devinrent aussi des motifs d’artisans. Le céladon coréen à figures humaines est rare."],"spots":[["Le plateau","Le plateau entre les deux, un carré blanc."],["Le personnage de gauche","Assis face au plateau."],["Le personnage de droite","L’adversaire, assis en face."],["Le saule","Des branches de saule pendent au-dessus d’eux, tracées à l’engobe noir."],["Le cadre de nuages","Des volutes en forme de nuages entourent le médaillon."],["Le craquelé","De fines fissures dans la glaçure, nées au refroidissement, car argile et glaçure ne se rétractent pas autant."]]},"kangra":{"title":"Couple jouant au chaupar sur une terrasse","artist":"Anonyme","date":"v. 1790–1800","place":"Inde (Pahari, école de Kangra)","game":"Chaupar","medium":"Dessin sur esquisse à l’ocre rouge","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Un dessin d’un artiste de Kangra, dans les collines pahari au pied de l’Himalaya. La première esquisse a été faite en rouge (ocre rouge), puis reprise en noir. Sans couleur par-dessus, on suit chaque trait des personnages et des objets.","Un homme et une femme, assis sur une terrasse de part et d’autre d’un plateau en croix, jouent au chaupar, ancien jeu de course indien sur la même croix que le pachisi, où l’on avance en lançant de longs dés (pasa). Les cases ne sont pas encore tracées sur le plateau. Des servantes s’occupent du couple."],"spots":[["Le plateau en croix","Un plateau en forme de croix, posé au sol. Ses cases ne sont pas encore tracées."],["La femme","La paume tournée vers le haut : sur le point de lancer les dés ?"],["L’homme","Turban à aigrette ; il tend la main vers le plateau."],["La servante de gauche","Elle tient un petit flacon et tend une étoffe."],["La servante de droite","Elle tient un ustensile à long manche et un petit récipient."],["L’esquisse rouge","Autour du turban, l’esquisse rouge apparaît sous les traits noirs."]]},"vuillard":{"title":"La Partie de dames (de Paysages et Intérieurs)","artist":"Édouard Vuillard","date":"1899","place":"France","game":"Dames","medium":"Lithographie en couleurs (état III/III) ; imprimée par Auguste Clot, éditée par Ambroise Vollard","size":"Image 33 × 25,7 cm (feuille 38 × 30,8 cm)","credit":"Don du Hanna Fund, 1951","p":["Ambroise Vollard, marchand de tableaux impressionnistes, fut aussi un grand éditeur d’estampes. En 1895, il commanda à Pierre Bonnard un album de 12 lithographies en couleurs, puis en publia bien d’autres, dont Paysages et Intérieurs de Vuillard, imprimé par le maître imprimeur Auguste Clot.","Bonnard et Vuillard faisaient partie des nabis — « prophètes » en hébreu —, qui cherchaient un art nouveau où la forme et la couleur expriment elles-mêmes le sentiment, et qui aimaient les scènes de la vie urbaine et familiale. Dans une pièce saturée de motifs, deux hommes s’affrontent au-dessus d’un damier tandis qu’une femme, debout, regarde. La note au crayon, en bas à gauche, se lit « partie de dames »."],"spots":[["Le damier","Un petit damier, les pions en place."],["L’homme de gauche","Un homme barbu avance la main au-dessus du damier."],["L’homme de droite","Son adversaire, penché sur le jeu dans un fauteuil, à moitié caché par la femme debout."],["La femme debout","La main au menton, elle suit la partie."],["La lampe","Une lampe contre le mur. Papier peint et tissus sont couverts de motifs."],["La note au crayon","En bas à gauche, au crayon : « partie de dames »."]]},"talbot":{"title":"Les Joueurs d’échecs (photographie ancienne)","artist":"Attribuée à William Henry Fox Talbot","date":"v. 1843–47","place":"Angleterre","game":"Échecs","medium":"Épreuve sur papier salé","size":"19,9 × 15 cm","credit":"Achat grâce aux fonds de M. et Mme Everett Kovler","p":["Le procédé négatif-positif inventé par Talbot, et la reproduction illimitée qu’il permettait, a dominé la photographie jusqu’à l’ère numérique. Ses premières expériences montrent à la fois son goût de la science et ses ambitions artistiques, et les chercheurs ont confirmé qu’il a pris au moins dix vues de joueurs d’échecs.","Celle-ci n’est peut-être pas de lui : cette épreuve et d’autres de la même scène ne sont pas signées et sont sur un papier différent de celui qu’il employait. Les modèles seraient le photographe Antoine Claudet et l’assistant de Talbot, Nicolaas Henneman ; selon des recherches récentes, les images auraient été faites dans l’atelier de Claudet, puis seraient passées à Henneman, qui les aurait remises à Talbot en paiement d’une dette (notice du musée)."],"spots":[["L’échiquier","L’échiquier sur la table, les pièces alignées."],["L’homme au haut-de-forme","Le chapeau sur la tête, il saisit une pièce."],["Le songeur","La main au menton, l’adversaire étudie la partie."],["Le rideau","Un rideau tombe derrière eux : un fond pour la prise de vue ?"],["Un autre chapeau","Un second haut-de-forme est posé sur le support à droite."]]},"pvl":{"title":"Hommes jouant aux dés","artist":"Maître PVL","date":"v. 1520","place":"Pays-Bas","game":"Dés","medium":"Gravure au burin sur papier","size":"9,4 × 9,4 cm (ronde)","credit":"Collection Charles Hack et Hearn Family Trust, achat 2023","p":["L’œuvre d’un graveur anonyme actif aux Pays-Bas au début du XVIe siècle, appelé Maître PVL d’après le monogramme « PVL » gravé en bas à gauche. Sur une estampe ronde qui tiendrait dans la paume, des traits fins et serrés construisent la profondeur de la pièce et la matière des étoffes.","Deux dés sont sur la table. Un homme penché et un jeune homme au col de fourrure pointent du doigt et se disputent, peut-être sur le compte. Derrière, des femmes regardent, et une cruche de vin est posée sous la table. Les dés sont liés aux jeux d’argent depuis l’Antiquité et furent interdits à maintes reprises."],"spots":[["Les dés","Deux dés qui roulent sur la table."],["Les mains qui pointent","Deux doigts se rencontrent sur la table : une querelle sur le compte ?"],["L’homme au large chapeau","Penché en avant ; ses manches bouffantes et tailladées étaient à la mode."],["Le jeune homme au col de fourrure","Grand chapeau et col de fourrure."],["Les femmes qui regardent","Des femmes suivent la partie par-derrière."],["Le monogramme","« PVL » en bas à gauche : seul indice du nom de l’artiste."]]},"kiyohiro":{"title":"Joueuses de sugoroku","artist":"Torii Kiyohiro","date":"v. 1750","place":"Japon (époque d’Edo)","game":"Ban-sugoroku","medium":"Estampe en couleurs (benizuri-e), ōban ; éditeur Urokogataya","size":"43,5 × 29,3 cm","credit":"Collection Clarence Buckingham","p":["Torii Kiyohiro fut un artiste d’ukiyo-e actif d’environ 1737 à 1776. Voici une benizuri-e, imprimée avec peu de planches de couleur — rose beni, vert… — dans les années qui précèdent l’apparition, en 1765, des nishiki-e polychromes.","Le jeu posé sur le support noir est le ban-sugoroku : deux joueurs lancent les dés et avancent des pions blancs et noirs ; le premier à sortir tous les siens gagne. Il appartient à la même famille que le backgammon, et les estampes ukiyo-e montrent souvent des femmes qui s’y adonnent. Derrière, une femme fume une longue pipe en regardant."],"spots":[["Le plateau","Un plateau de sugoroku sur pied, avec des pions blancs et noirs."],["La figure de gauche","Elle tend la main pour déplacer un pion."],["La femme de droite","Penchée sur le plateau, l’adversaire étudie les pions."],["La femme à la pipe","Une longue pipe kiseru à la main, elle suit la partie par-derrière."],["La main levée","La femme de droite brandit un petit objet noir : le gobelet à dés ?"],["La signature","« Torii Kiyohiro hitsu », avec le sceau de l’éditeur Urokogataya."]]},"ingram":{"title":"Le Jeu d’échets chinois","artist":"John Ingram, d’après François Boucher","date":"1741–63","place":"France (Paris)","game":"Xiangqi","medium":"Eau-forte et burin","size":"Feuille 39,4 × 27,7 cm (planche 24,5 × 16,4 cm)","credit":"Collection Elisha Whittelsey, 1966","p":["Un dessin du peintre François Boucher, gravé par John Ingram, né à Londres. Installé à Paris, Ingram grava entre 1741 et 1763 une série d’estampes d’après les chinoiseries de Boucher — la Chine telle que l’imaginaient les Européens. Le titre se lit « LE JEU D'ECHETS CHINOIS ».","Une femme au chignon haut déplace une pièce sur le plateau posé sur ses genoux, sous le regard d’un petit enfant. On y voit le xiangqi, pourtant les vraies pièces de xiangqi sont toutes des disques plats, alors qu’ici de hautes pièces voisinent avec de petites pièces carrées. Le palmier et la figure assise sur l’urne relèvent moins de la Chine que du pays lointain dont rêvait l’Europe d’alors."],"spots":[["Plateau et pièces","Le plateau sur ses genoux, avec des pièces hautes et carrées. Les vraies pièces de xiangqi sont des disques plats."],["La main sur la pièce","Sa main droite déplace une pièce."],["La joue dans la main","La main gauche au menton, elle regarde le plateau."],["L’enfant qui regarde","Un enfant debout près du plateau suit la partie."],["La figure sur l’urne","Une figure assise en tailleur sur une grande urne."],["Titre et noms","« Dessiné par Fr. Boucher », « Gravé par Ingram » et le titre « LE JEU D'ECHETS CHINOIS »."]]},"posada":{"title":"Le Jeu de l’oie","artist":"José Guadalupe Posada","date":"1909","place":"Mexique","game":"Jeu de l’oie","medium":"Gravure en relief sur zinc, sur papier","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Une feuille à jouer, faite par le graveur mexicain Posada — célèbre pour ses calaveras, ses squelettes — pour l’éditeur de Mexico Antonio Vanegas Arroyo. La banderole en bas à gauche porte « JUEGO DE LA OCA » (jeu de l’oie), et le parcours s’enroule de la case 1 jusqu’à la 63, au centre.","La règle (EXPLICACION) est imprimée au milieu : un premier lancer de 5 et 4 mène au 26, de 6 et 3 au 53. Qui tombe sur une oie (un oiseau) compte encore autant ; à l’auberge (Venta, 19) on attend deux tours ; au puits (Poso, 31) et à la prison (Carcel, 52) on reste jusqu’à ce qu’un autre vienne ; le labyrinthe (42) renvoie au 39 et la mort (Muerte, 58) au départ. Il faut tomber juste sur 63. On payait aussi des mises sur certaines cases : c’était un jeu d’argent."],"spots":[["La règle","L’« EXPLICACION » du centre : l’effet de chaque case et quand payer la mise."],["La case 1","Le départ. De là, le parcours s’enroule vers le centre."],["Le puits (31)","Un puits comme une fontaine. On y reste jusqu’à l’arrivée d’un autre joueur."],["La mort (58)","La case à tête de mort : retour au départ."],["La banderole du titre","« JUEGO DE LA OCA » sur la banderole en bas à gauche, avec des enfants qui jouent dessous."],["Le nom de l’éditeur","La banderole de la déesse porte « IMPRENTA DE A. VANEGAS ARROYO », la maison qui publia beaucoup d’estampes de Posada."]]},"jintile":{"title":"Carreau à décor de femmes jouant à un jeu de plateau","artist":"Anonyme","date":"XIIIe siècle","place":"Chine (dynastie Jin)","game":"Jeu de plateau (sans doute le go)","medium":"Terre cuite (relief moulé)","size":"H. 27,3 cm, l. 24,8 cm, ép. 5,4 cm","credit":"Achat, dons des Friends of Asian Art, 2002","p":["Un carreau en relief fait sous les Jin (1115–1234), dynastie du peuple jurchen qui régna sur la Chine du Nord. Sous un arbre en fleurs, deux femmes sont assises face à face sur une estrade, un plateau entre elles.","Le plateau porte un quadrillage fin : elles jouent sans doute au go. Celle de droite se penche et montre le plateau du doigt, celle de gauche regarde. Beaucoup de tombes d’époque Jin en Chine du Nord étaient revêtues de briques sculptées de scènes de la vie quotidienne, et ce carreau ornait probablement l’une d’elles."],"spots":[["Le plateau","Un plateau finement quadrillé, sans doute un goban."],["La main qui montre","La femme de droite désigne le plateau. Son prochain coup ?"],["La femme de gauche","Les cheveux relevés, elle regarde le plateau."],["La femme de droite","Penchée vers le plateau."],["L’arbre en fleurs","Les branches d’un arbre en fleurs s’étendent au-dessus d’elles."],["L’estrade","L’estrade où elles sont assises, avec un bandeau festonné entre les pieds."]]},"kyosai":{"title":"Un pet renverse une partie de go (d’un album de croquis)","artist":"Kawanabe Kyōsai","date":"Milieu à fin du XIXe siècle","place":"Japon (époques d’Edo à Meiji)","game":"Go","medium":"Une double page d’un album en accordéon de 26 doubles feuillets ; encre et couleurs sur papier","size":"Album (fermé) 28 × 18 cm","credit":"Don d’Anne et Anthony d’Offay en l’honneur d’Evan Turner","p":["Une scène d’un album de croquis de Kawanabe Kyōsai (1831–1889), peintre actif de la fin du shogunat à l’ère Meiji, tracée à traits rapides et libres sur les pages d’un album en accordéon. Formé à la technique exigeante de l’école Kanō, Kyōsai était aussi adoré pour ses démons, caricatures et satires.","Le titre du musée dit tout : « Un pet renverse une partie de go ». À gauche, un homme coiffé d’un bonnet noir se penche ; à droite, le goban s’envole, les bols déversent une pluie de pierres et l’adversaire tombe à la renverse. Une partie sérieuse ruinée d’un seul coup : Kyōsai reprend, de son pinceau rapide, le vieil humour japonais du pet, déjà présent dans des rouleaux médiévaux."],"spots":[["L’homme au bonnet noir","Penché, le derrière en avant : la cause du désastre ?"],["Le goban qui s’envole","Le plateau quadrillé part de travers."],["Bols et pierres","Deux bols se renversent et les pierres pleuvent."],["L’éventail","Un éventail ouvert s’envole près du plateau."],["L’adversaire renversé","Sur le dos, les yeux écarquillés."],["Le trait","Des traits d’encre énergiques, comme tracés d’un jet sans esquisse."]]},"yokuts":{"title":"Plateau de jeu d’argent","artist":"Vannière yokuts (nom inconnu)","date":"v. 1900","place":"États-Unis (près de Dunlap, Californie)","game":"Huuchuish (dés en coquille de noix)","medium":"Fibres végétales (vannerie spiralée)","size":"H. 5,1 cm, diam. 61 cm","credit":"Achat grâce aux fonds de Mrs. Leonard S. Florsheim Jr.","p":["Beaucoup de peuples autochtones de Californie pratiquaient des jeux de hasard. Ce plateau servait au huuchuish, un jeu de dés réservé aux femmes : on lançait huit dés en coquille de noix sur le plateau, et l’on comptait les points avec des bâtonnets.","Le décor circulaire tissé dans le plateau montre le jeu lui-même — les dés, les bâtonnets de marque et les joueuses (notice du musée). C’est un instrument de jeu qui porte l’image de son propre jeu. Sur la photographie, des dés en coquille de noix sont posés sur le plateau et autour."],"spots":[["Les joueuses","Des figures font le tour du bord : celles qui prennent part au jeu."],["Bâtonnets de marque","Des faisceaux de petits traits verticaux : les bâtonnets pour compter."],["Motifs ronds","De petits motifs ronds : les dés, peut-être ?"],["Un dé en noix","Un dé en coquille de noix. On en lançait huit sur le plateau."],["La bande de triangles","Une bande de triangles sombres fait le tour."],["Le centre","La spirale part du centre, entourée d’un cercle en tirets."]]},"hokkei":{"title":"Ushiwakamaru bat Benkei au sugoroku","artist":"Totoya Hokkei","date":"v. 1825","place":"Japon (époque d’Edo)","game":"Ban-sugoroku","medium":"Surimono (estampe en couleurs, shikishiban)","size":"21,8 × 19,1 cm","credit":"Don d’Helen C. Gunsaulus","p":["Un surimono de Totoya Hokkei (1780–1850), élève d’Hokusai. Les surimono étaient des estampes de commande privée — souvent par des cercles de poésie, avec leurs propres vers — plus luxueuses que l’ukiyo-e du commerce, avec beau papier et pigments métalliques.","Ushiwakamaru, nom d’enfance du héros Minamoto no Yoshitsune, et le gigantesque moine-guerrier Benkei. Leur célèbre rencontre fut un duel sur le pont Gojō de Kyoto, mais ici l’affrontement devient une partie de sugoroku : l’enfant est assis, serein, derrière le plateau, et Benkei, la hallebarde au dos, se gratte la tête, vaincu. Une transposition ludique, semble-t-il."],"spots":[["Le plateau de sugoroku","Un plateau en forme de boîte, avec des pions blancs et noirs."],["Benkei se grattant la tête","En armure, le vaincu se gratte la tête."],["Ushiwakamaru","Le jeune héros, assis derrière le plateau."],["La hallebarde","La lame de la grande naginata de Benkei."],["Le poème","Des vers en haut à droite, sans doute du cercle qui commanda l’estampe."],["La signature","La signature de Hokkei dans le cartouche en bas à droite."]]},"vorsterman":{"title":"Joueurs de trictrac (scène nocturne)","artist":"Lucas Emil Vorsterman, d’après Adam de Coster","date":"v. 1630","place":"Flandre (Anvers)","game":"Backgammon","medium":"Gravure au burin sur papier ivoire","size":"Image 25,5 × 34,4 cm","credit":"Collection Bernard F. Rogers","p":["Adam de Coster était, vers 1630 à Anvers, un peintre réputé de scènes nocturnes à la chandelle, au moment où Vorsterman, dans la même ville, gravait les œuvres de contemporains en vogue. Élève de Rubens, Vorsterman se brouilla avec son maître et partit en Angleterre ; il fit ensuite des gravures plus contrastées, plus stylisées, caravagesques, comme celle-ci.","Autour d’une table dans une pièce sombre, des hommes se penchent sur un plateau de trictrac. À la manière de De Coster, deux flammes de chandelle éclairent les visages autour de la table (notice du musée). À droite, un jeune joueur de luth nous regarde."],"spots":[["Le plateau","Un trictrac ouvert comme une boîte sur la table."],["La chandelle","Une chandelle sur son bougeoir ; sa flamme éclaire les visages."],["L’homme à la pipe","Coiffé d’un large chapeau, il fume en regardant la partie."],["L’homme de dos","Penché, les mains sur la table."],["Le joueur de luth","Un jeune homme au luth qui nous sourit."],["Les noms","« A. De Coster pi. » en bas à gauche, « Vorsterman » en bas à droite."]]},"zorn":{"title":"Joueurs d’échecs","artist":"Anders Zorn","date":"1891","place":"Suède","game":"Échecs","medium":"Eau-forte sur papier vergé ivoire","size":"Image 13,5 × 9,6 cm (cuivre 13,9 × 10 cm)","credit":"Collections d’eaux-fortes d’Anders Zorn de Wallace L. DeWolf et Charles Deering","p":["Une eau-forte de l’artiste suédois Anders Zorn (1860–1920), célèbre dans le monde pour ses portraits à l’huile et à l’aquarelle, qui laissa aussi un important œuvre gravé. Le cuivre n’est pas plus grand qu’une main.","Il suffit de traits rapides et obliques superposés pour faire surgir du cuivre une pièce sombre et deux personnes. L’homme au premier plan, de dos, se penche sur l’échiquier ; en face, l’autre baisse les yeux et réfléchit au coup suivant. Les pièces sont dessinées d’un trait fin. On ne sait pas qui a posé."],"spots":[["L’échiquier et les pièces","La zone claire en bas est l’échiquier ; les petits traits verticaux sont les pièces."],["L’homme au premier plan","De dos, penché sur l’échiquier."],["L’adversaire","Tête baissée, les yeux sur l’échiquier."],["Le fond sombre","Le fond de la pièce, fait de lignes verticales."],["Les traits obliques","Le manteau est fait de traits diagonaux rapides superposés."],["La signature","Signé « Zorn » au crayon sous le cuivre."]]},"harunobu-sugoroku":{"title":"Regarder la partie (sugoroku)","artist":"Suzuki Harunobu","date":"v. 1766","place":"Japon (époque d’Edo)","game":"Ban-sugoroku","medium":"Estampe en couleurs (chūban, surimono)","size":"28,5 × 21 cm","credit":"Collection Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) fut la figure centrale de la naissance, vers 1765, des nishiki-e, estampes polychromes imprimées avec de nombreuses planches. Celle-ci est un surimono d’édition privée, dont les couleurs douces et superposées montrent la nouveauté.","Dans une pièce aux pruniers en fleurs, deux jeunes filles jouent sur un plateau de sugoroku en forme de boîte, tandis qu’une troisième, debout, regarde. Des pions blancs et noirs couvrent le plateau ; celle de gauche en déplace un, celle de droite tend la main. La porte coulissante du fond est peinte d’une cascade et de pins."],"spots":[["Le plateau de sugoroku","Un plateau de ban-sugoroku en forme de boîte, aux pions blancs et noirs."],["La jeune fille de gauche","En kimono à grues de papier, elle déplace un pion."],["La jeune fille de droite","Penchée, elle tend la main vers le plateau."],["La spectatrice","Debout, elle regarde la partie, un objet à long manche à la main."],["Le prunier","Un prunier blanc étend ses branches depuis le haut."],["La porte peinte","Une porte coulissante peinte d’une cascade et de pins."]]},"kota":{"title":"Le maharao Kishor Singh II de Kota adorant Krishna sous la forme de Brij Rajji","artist":"Anonyme","date":"v. 1825","place":"Inde (Rajasthan, Kota)","game":"Pachisi","medium":"Tempera à la gomme, argent et or sur papier","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Le souverain du petit État princier de Kota (r. 1819–28), vêtu en prêtre de la secte Pushti Marg, présente une lampe à cinq flammes. Dans le petit sanctuaire de l’autel se dressent des images en métal de Krishna entouré de deux épouses — une idole vénérée seulement à Kota.","Une multitude de lampes de verre pend du plafond, et sur les marches menant à l’autel sont disposés des jouets et des jeux pour amuser Krishna et ses compagnons : éléphants de laiton, vaches d’argent, balles et un plateau de pachisi (notice du musée). Le tissu rouge en croix est ce plateau : le pachisi offert comme jouet au dieu."],"spots":[["Le plateau de pachisi","Le tissu rouge en croix sur les marches : un plateau de pachisi."],["Éléphants","Deux éléphants de laiton près du plateau."],["Balles","Des balles dorées sur la marche supérieure."],["Krishna","Les images de Krishna et de deux épouses dans le sanctuaire."],["Le souverain et sa lampe","Vêtu en prêtre, il présente une lampe à cinq flammes."],["Lampes de verre","Une foule de lampes de verre pend du plafond."]]},"coyote":{"title":"Le Jeu du coyote","artist":"Suiveur de José Guadalupe Posada","date":"Non daté","place":"Mexique","game":"Coyote et poules (famille du renard et des oies)","medium":"Gravure en relief sur zinc, sur papier","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Une feuille à jouer, imprimée en relief sur zinc comme celles que Posada faisait pour les presses populaires de Mexico. En haut, « JUEGO DEL COYOTE » (jeu du coyote) ; tout autour, des coyotes attaquent le poulailler et un homme brandit un bâton pour en chasser un. La bande du bas indique « Propriété d’Ildefonso T. Orellana ».","La règle est imprimée dans l’« EXPLICACION » en bas : deux joueurs, l’un avec quinze poules, l’autre avec un seul coyote. Les poules avancent ou vont de côté mais ne reculent jamais ; le coyote se déplace en tous sens et mange une poule en sautant par-dessus si la place derrière est libre. Les poules gagnent en enfermant le coyote. C’est le même jeu de chasse que le renard et les oies européen."],"spots":[["La place du coyote","La tête de coyote dans le cercle central : le coyote part de là."],["Les places des poules","Les cercles aux poules : on y pose leurs pions."],["La règle","L’« EXPLICACION » : pions, déplacements et victoire."],["Le titre","« JUEGO DEL COYOTE » — jeu du coyote."],["Un coyote sur une poule","En bas à gauche, un coyote s’en prend à une poule."],["L’homme au bâton","En haut à droite, un homme lève un bâton contre un coyote."]]},"mons":{"title":"Trictrac pour Mons (Bergen), 1709","artist":"Pieter Nolpe (planche et éditeur)","date":"Planche 1623–53 ; tirage v. 1709","place":"Pays-Bas (Amsterdam)","game":"Trictrac (de la famille du backgammon)","medium":"Eau-forte, burin et vers typographiés","size":"Feuille 35,8 × 18,6 cm (cuivre 12,9 × 17,5 cm)","credit":"","p":["Quatre hommes jouent au trictrac autour d’une table. Selon la notice du musée, les lettres A–D désignent le duc de Marlborough, l’électeur de Bavière, le seigneur d’Ouwerkerk et le duc de Villeroy. C’est une satire du siège et de la prise de Mons (Bergen en néerlandais) aux Français par les Alliés en 1709, présentée comme une partie dont l’enjeu est la ville. Dans la pièce du fond (E), le roi Philippe V d’Espagne est avec une femme.","Le cuivre est signé de Pieter Nolpe comme graveur et éditeur, mais Nolpe est mort au début des années 1650 : on a sans doute retiré une vieille planche du XVIIe siècle en y ajoutant des lettres et un nouveau poème. Celui-ci commence en disant que le jeu des grands seigneurs n’est que tiktak et verkeer (deux jeux de tables), puis raille chaque joueur."],"spots":[["Le plateau","Le trictrac sur la table : la ville est l’enjeu."],["A, Marlborough","Debout, il regarde le plateau : le général anglais des Alliés."],["B, l’électeur de Bavière","Tête nue, affalé sur sa chaise."],["C, Ouwerkerk","Au chapeau à plumes : le général hollandais."],["E, la pièce du fond","Au fond, Philippe V avec une femme dans la chambre."],["Le poème","Vers néerlandais imprimés dessous, raillant les joueurs A à E."]]},"stembus":{"title":"L’Urne : un jeu de l’oie politique","artist":"Johan Michaël Schmidt Crans (graveur)","date":"1867","place":"Pays-Bas","game":"Jeu de l’oie (satire)","medium":"Lithographie","size":"66 × 50 cm","credit":"","p":["Une estampe satirique en forme de jeu de l’oie, parue avec l’hebdomadaire De Nederlandsche Spectator, n° 9, du 2 mars 1867, accompagnée d’une feuille volante de règles (notice du musée). Les cases portent les portraits des ministres de l’époque.","On part du Binnenhof, le parlement de La Haye, et l’on arrive au centre, case 64, « Insulinde » — nom poétique des Indes néerlandaises —, où un portrait peint du ministre Pieter Mijer pend à l’île de Java. Mijer était passé de ministre des Colonies à gouverneur général des Indes, et cette nomination avait déclenché une tempête politique. La case de plus, une au-delà des 63 habituelles, est sans doute là pour la chute."],"spots":[["Le départ","Le bâtiment en haut à gauche : on part du Binnenhof de La Haye."],["Le portrait de Mijer","Case 63 : un portrait encadré de Pieter Mijer, suspendu à l’île par des cordes."],["Insulinde 64","L’île et le nombre 64 au centre : l’arrivée."],["L’urne","« DE STEMBUS » (l’urne) en bas à droite : la boîte du titre."],["Les ministres","Les visages des ministres du moment apparaissent dans les cases."],["Le coq","Un coq dans une case ; on ignore de quoi il se moque."]]},"koorai":{"title":"Coréens autour d’un jeu de plateau (d’après le Nippon de Siebold)","artist":"James Erxleben (lithographe), d’après un dessin de « Toioske »","date":"1832–52","place":"Pays-Bas (Leyde) / Coréens","game":"Jeu de plateau (sans doute le go)","medium":"Lithographie teintée, coloriée à la main","size":"Feuille 38 × 55,5 cm","credit":"Don de F. G. Waller","p":["Une planche de NIPPON, la grande œuvre que le médecin d’origine allemande Philipp Franz von Siebold publia à Leyde d’après ce qu’il avait vu au comptoir néerlandais de Nagasaki (1823–30). Elle porte « TAB. I » en haut à droite et « KOORAI » (Corée) en bas, avec « une famille de pêcheurs » en néerlandais et en allemand. Erxleben l’a dessinée sur pierre ; la planche nomme le dessinateur « Toioske ».","Quatre hommes assis par terre entourent un plateau ; à gauche une femme tient un petit enfant par la main, à droite un homme debout tient un long bâton et une bourse. Devant, un chapeau noir à large bord (gat) est posé au sol. Le plateau montre un quadrillage et des pierres rondes : sans doute du go (baduk en coréen), bien que la notice dise seulement « un jeu de plateau »."],"spots":[["Le plateau","Quadrillage et pierres rondes : sans doute une partie de go."],["Le chapeau noir","Un chapeau noir à large bord (gat) au sol."],["Mère et enfant","Une femme tenant un enfant regarde la partie."],["L’homme debout","Debout, avec un long bâton et une bourse."],["L’homme penché","En veste bleue, il scrute le plateau."],["Le titre","« KOORAI » (Corée), avec « une famille de pêcheurs » en néerlandais et en allemand."]]},"cairo":{"title":"Groupe autour d’un jeu de plateau devant un café (Le Caire)","artist":"Délié & Béchard (Hippolyte Délié et Émile Béchard)","date":"v. 1869–90","place":"Égypte (Le Caire)","game":"Jeu de plateau (sans doute les échecs)","medium":"Tirage sur papier albuminé","size":"10,8 × 16,4 cm","credit":"","p":["Une photographie d’Hippolyte Délié et Émile Béchard, photographes français installés au Caire. Le carton porte le nom de l’atelier, « Au Jardin de l’Esbékieh », et « Caire (Égypte) ». Les voyageurs achetaient ce genre d’images en souvenir de l’Égypte.","Des hommes assis par terre devant une boutique à fenêtre grillagée entourent un plateau posé sur un support bas. De hautes pièces s’y dressent : sans doute des échecs (chatrandj en arabe), bien que la notice du musée dise seulement « un jeu de plateau ». Chacun reste immobile pour la longue pose."],"spots":[["Plateau et pièces","Le plateau sur un support bas, aux hautes pièces : sans doute les échecs."],["La fenêtre grillagée","Une fenêtre à treillis de bois, typique des vieilles maisons du Caire."],["L’homme au bâton","Assis avec un bâton, il suit la partie."],["Le panier","Un panier tressé posé au sol."],["L’enfant qui regarde","Un enfant regarde le plateau par-derrière."],["Le nom de l’atelier","« AU JARDIN DE L’ESBÉKIEH » et « CAIRE (EGYPTE) » sur le carton."]]},"vanmour":{"title":"Compagnie d’Arméniens jouant aux cartes","artist":"Jean-Baptiste Vanmour","date":"v. 1720–37","place":"Empire ottoman (Istanbul)","game":"Cartes","medium":"Huile sur toile","size":"44,5 × 58,5 cm","credit":"","p":["Né en Flandre, Vanmour gagna Istanbul en 1699 avec l’ambassadeur de France et vécut dans la ville jusqu’à sa mort, peignant les cérémonies de la cour et la vie de ses habitants. Le musée précise que les vêtements des hommes les désignent comme Arméniens.","À la lueur d’une grande chandelle, hommes et femmes jouent aux cartes autour d’une table couverte d’un tapis rouge. Des cartes sont distribuées sur la table, et certains scrutent leur jeu. Dans le coin gauche, une vieille femme file. La notice ne dit pas de quel jeu il s’agit."],"spots":[["Cartes sur la table","Des cartes sur la table au tapis rouge."],["La grande chandelle","Une seule chandelle éclaire toute la compagnie."],["La vieille fileuse","Une vieille femme file dans le coin gauche."],["Femme regardant son jeu","À l’extrême droite, une femme examine ses cartes."],["L’homme en fourrure","Un homme au manteau bordé de fourrure ; l’habit désigne des Arméniens."],["Penché sur la table","Un personnage se penche sur la table, cartes en main."]]},"algiers":{"title":"Trois hommes jouant à un jeu de plateau (Alger)","artist":"Anonyme","date":"1851–1900","place":"Algérie (Alger)","game":"Jeu de plateau (sans doute le trictrac)","medium":"Tirage sur papier albuminé","size":"14,0 × 10,0 cm","credit":"","p":["Une photographie anonyme portant, écrit à la main sous l’image, « Alger ». Avec des chaises et une petite table devant un fond uni, elle a sans doute été prise en atelier. Voyageurs et collectionneurs achetaient de telles images de gens d’Afrique du Nord.","Deux hommes se font face devant un plateau à rebord ; celui de droite tend la main vers une pièce. Des pions ronds sont empilés sur le plateau : sans doute le trictrac ou backgammon (appelé tawla dans la région, entre autres), même si la notice dit seulement « un jeu de plateau ». Sur la petite table devant, le service à café."],"spots":[["Plateau et pions","Un plateau à rebord où s’empilent des pions ronds."],["Le spectateur debout","Un homme à la ceinture d’étoffe regarde la partie, debout derrière."],["Le vieil homme, à gauche","Un homme âgé, la tête enturbannée, pensif."],["L’homme de droite","Un linge blanc sur la tête, il se penche sur le plateau."],["Le service à café","Plateau et petites tasses sur une table ajourée."],["La main qui joue","La main du joueur de droite, prête à prendre un pion."]]},"circo":{"title":"Jeu du cirque (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Non daté","place":"Mexique","game":"Jeu d’argent à deux dés","medium":"Gravure en relief ou similigravure sur papier vélin chamois","size":"26,2 × 35,0 cm","credit":"","p":["Une feuille de jeu attribuée, avec un point d’interrogation, au graveur mexicain Manuel Manilla. En bas à droite figure son vendeur, l’imagerie « El Teatro », avec son adresse. Ces feuilles bon marché se vendaient dans la rue et servaient sans doute de plateau telles quelles.","Au centre, un chapiteau de cirque, entouré d’écuyers acrobates, d’une pyramide humaine, d’un hercule et d’autres, chacun marqué d’un nombre de 2 à 12. L’« Esplicacion » en haut à gauche dit que tous, enfants compris, peuvent jouer : on lance deux dés et l’on mise sur la case obtenue, ou l’on prend la mise qui s’y trouve. Qui fait douze rafle tout."],"spots":[["Le chapiteau","Le titre « JUEGO DEL CIRCO » et le chapiteau, case 12."],["La règle","La règle, sous le titre « ESPLICACION »."],["L’écuyère","Une danseuse sur un cheval au galop : case 6."],["La tour humaine","Un homme debout sur les épaules d’un autre : case 4."],["L’hercule","Un homme soulevant un poids en forme de canon : case 8."],["Le nom de l’imagerie","« De venta, Estampería “El Teatro” » et l’adresse."]]},"loteria":{"title":"Jeu de lotería","artist":"José Guadalupe Posada","date":"1880–1913","place":"Mexique","game":"Lotería (jeu d’images annoncées)","medium":"Gravure en relief ou similigravure sur papier vélin chamois","size":"30,0 × 40,0 cm","credit":"","p":["Le graveur mexicain Posada dessina d’innombrables images pour l’éditeur de Mexico Antonio Vanegas Arroyo, dont les feuilles bon marché diffusaient nouvelles, chansons et jeux. Celle-ci porte le titre « JUEGO DE LOTERIA » et le nom de Vanegas Arroyo.","Trente-huit petites images légendées couvrent la feuille : l’étoile, la lune, le scorpion, le diable, la tête de mort, le coq, l’imprimerie, etc. À la lotería, proche du loto ou du bingo, un meneur tire des cartes et annonce les images, que les joueurs marquent sur leur planche avec des haricots ou autre chose. La feuille était sans doute découpée en cartes."],"spots":[["Titre et éditeur","« JUEGO DE LOTERIA » et le nom de la maison Vanegas Arroyo."],["L’étoile","« ESTRELLA », première image en haut à gauche."],["La lune","« LUNA », un croissant à visage."],["La Mort","« MUERTE » : un squelette à la faux jouant du pipeau."],["Le tlachiquero","« TLACHIQUERO » : un homme qui recueille la sève de l’agave."],["L’imprimerie","« IMPRENTA » : des ouvriers à la presse, là où se faisaient ces feuilles."]]},"jeupol":{"title":"« Jeu polonais », ou damier","artist":"Anonyme","date":"1833–1900","place":"Belgique ou Pays-Bas","game":"Dames (damier de 10 × 10)","medium":"Gravure sur bois et texte typographié","size":"32,2 × 39,6 cm","credit":"","p":["Une feuille volante titrée en français et en néerlandais, « JEU POLONAIS OF DAMSPEL ». Le « jeu polonais » désignait en France les dames sur damier de 10 × 10. En haut à droite figure le numéro d’éditeur, « n. 106 ».","Comme l’indique la notice du musée, on compte 100 cases, 50 blanches et 50 noires, avec des bordures ornementales à gauche et à droite. Aucun pion n’est imprimé : c’était sans doute un damier bon marché utilisé tel quel, avec des haricots ou des boutons. Le papier garde ses plis."],"spots":[["Le titre","Les mots « JEU POLONAIS OF DAMSPEL »."],["Le numéro","Le numéro d’éditeur « n. 106 »."],["La bordure gauche","Une colonne de rosaces."],["La bordure droite","Le même motif de l’autre côté."],["Les cent cases","Le damier de 10 × 10 ; les cases foncées sont hachurées."],["Le pli","Un pli resté dans le papier ; peut-être le portait-on plié."]]},"dkaart":{"title":"Jeu de domino et de cartes à découper","artist":"Anonyme (Brepols)","date":"1800–1833","place":"Belgique (Turnhout)","game":"Dominos et cartes","medium":"Gravure sur bois coloriée en bleu, rouge et jaune ; texte typographié","size":"34,3 × 41,9 cm","credit":"","p":["Selon la notice du musée, la feuille porte 32 cartes à jouer et 28 dominos à découper. C’est le numéro 114 du catalogue de l’éditeur Brepols, avec en pied le revendeur « D. Pouwels, Bergen-op-Zoom ». Le titre est en néerlandais et en français.","À gauche, les 28 dominos, du double blanc au double six, forment un triangle. À droite, 32 cartes, du sept au dix plus les figures et les as de chaque couleur : un jeu pour le piquet et autres. Comme personne ne l’a découpée, on la voit telle qu’elle sortit de presse."],"spots":[["Le titre","Les mots « DOMINO EN KAARTSPEL »."],["Double blanc","Le sommet du triangle : le domino sans points."],["Double six","La plus forte pièce, au bout de la dernière rangée."],["As de pique","La deuxième carte de la colonne de gauche."],["Une figure","Un roi colorié de rouge, bleu et jaune."],["Le revendeur","« D. POUWELS, Bergen-op-Zoom » en bas."]]},"apen":{"title":"Deux singes jouant au trictrac","artist":"Quirin Boel, d’après David Teniers","date":"1635–1690","place":"Flandres","game":"Trictrac","medium":"Eau-forte","size":"11,0 × 14,5 cm","credit":"","p":["Planche d’une suite, un titre et six planches, où des singes miment les occupations humaines. En bas à gauche : « D. Teniers inventa et publia, avec privilège » ; Quirin Boel a gravé le dessin du peintre flamand Teniers.","Comme le décrit la notice du musée, deux singes assis par terre ont un trictrac entre eux. Celui de gauche boit du vin dans un verre ; celui de droite, coiffé d’un chapeau à plume de coq, tend la main vers une dame. Sans doute une moquerie des hommes livrés au vin et au jeu."],"spots":[["Le trictrac","Un tablier pliant posé au sol, avec ses flèches et ses dames."],["Le singe de gauche","Un singe en veste, assis devant le jeu."],["Le verre","Le verre levé par le singe de gauche."],["Le chapeau à plume","Une plume de coq au chapeau du singe de droite."],["La cruche","Une cruche aux pieds du singe de gauche."],["L’inscription","« D Teniers in et excud cum privilegio »."]]},"dstereo":{"title":"Hommes jouant aux dominos à une table (stéréographie)","artist":"Anonyme","date":"1850–1880","place":"Inconnu (inscription en néerlandais)","game":"Dominos","medium":"Tirage sur papier albuminé (vue stéréoscopique)","size":"8,5 × 17,0 cm","credit":"","p":["Une vue stéréoscopique : deux photographies presque identiques côte à côte. Regardées dans un stéréoscope, elles se fondent en une scène en relief. Au bord gauche, on lit à la main « Het dominospel » (le jeu de dominos).","Une table a été sortie au soleil devant un bâtiment, et des hommes en bras de chemise tiennent leurs dominos. Deux regardent la partie debout ; celui de droite porte un bonnet blanc. Comme chacun devait rester immobile, la scène a sans doute été arrangée pour l’appareil."],"spots":[["Les dominos","Des dominos tenus face cachée."],["L’homme au bonnet blanc","Assis à droite, ses dominos en main."],["L’homme au foulard","Debout, il regarde la partie."],["L’homme de gauche","Un jeune homme accoudé, penché sur son jeu."],["L’inscription","« Het dominospel. » écrit au bord gauche."],["La seconde image","La vue de droite, prise d’un point un peu décalé : ensemble, elles donnent le relief."]]},"gojo":{"title":"Deux femmes jouant au go","artist":"Anonyme","date":"1870–1891","place":"Japon","game":"Sans doute le go","medium":"Tirage albuminé colorié à la main","size":"9,0 × 13,5 cm","credit":"","p":["Une photographie en noir et blanc coloriée au pinceau. De telles images se faisaient dans les ateliers de Yokohama et d’ailleurs, en souvenirs pour les étrangers. Celle-ci était collée dans un album de photos d’un voyage à Manille.","Devant un décor d’alcôve et un paravent, deux femmes sont assises de part et d’autre d’un plateau à pieds ; celle de gauche pose une pierre. Des pierres blanches et noires sont sur le plateau : sans doute le go, même si la notice du musée dit « un jeu de plateau ». Sur le plateau de service devant, des douceurs et des bols."],"spots":[["Le goban et les pierres","Un épais plateau à pieds, avec pierres blanches et noires."],["La main qui joue","La femme de gauche pose une pierre."],["La femme de gauche","Elle se tourne vers nous ; son obi forme un grand nœud."],["La femme de droite","En kimono rayé, la main près du plateau."],["Plateau et bols","Douceurs et tasses devant elles."],["Les fleurs","Un vase de fleurs sur un support, derrière."]]},"meade":{"title":"Deux hommes jouant aux échecs","artist":"Charles Richard Meade et Henry William Mathew Meade","date":"1852","place":"États-Unis","game":"Échecs","medium":"Daguerréotype","size":"6,9 × 8,3 cm","credit":"","p":["Un daguerréotype de l’atelier des frères Meade, photographes nés en Angleterre et installés en Amérique. Le daguerréotype forme l’image directement sur une plaque de cuivre argentée : chacun est unique et ne peut être retiré. Celui-ci est logé dans un petit étui de cuir, derrière un passe-partout doré.","Deux jeunes gens font face à un échiquier posé sur un guéridon ; celui de gauche a les doigts sur une pièce. Celui de droite, la main sur la poitrine, étudie la position. Comme il fallait rester longtemps immobile, le coup est sans doute posé."],"spots":[["L’échiquier","L’échiquier et les pièces blanches, sur un guéridon tendu de tissu fleuri."],["L’homme de gauche","Les doigts sur une pièce."],["L’homme de droite","Il regarde l’échiquier."],["La main sur la poitrine","La main pensive du joueur de droite."],["Le tissu","Un petit guéridon couvert d’étoffe fleurie."],["Le passe-partout doré","Le cadre doré et l’étui qui protègent la plaque."]]},"weiqidai":{"title":"Paysage avec des immortels taoïstes jouant au weiqi","artist":"Attribué à Dai Jin","date":"Dynastie Ming, XVe–XVIe siècle","place":"Chine","game":"Weiqi (go)","medium":"Rouleau vertical ; encre et couleurs sur soie","size":"175,2 × 106,7 cm","credit":"","p":["Un grand rouleau vertical attribué au peintre Ming Dai Jin (v. 1388–1462). Originaire du Zhejiang et connu pour ses paysages vigoureux, il passa plus tard pour le fondateur de l’école Zhe. Sous des falaises vertigineuses et un grand arbre, les personnages sont minuscules.","À l’ombre, deux immortels sont assis devant un tablier de weiqi quadrillé, un plat de fruits et une jarre à côté. La silhouette accroupie à gauche évoque le bûcheron qui regarda des immortels jouer dans la montagne jusqu’à ce que le manche de sa hache pourrisse (la légende de Lanke), même si le titre du musée ne parle que d’immortels jouant au weiqi."],"spots":[["Le goban","Un tablier à rebord, finement quadrillé."],["L’immortel barbu","Un immortel à longue barbe, assis tranquillement."],["L’immortel au bonnet bleu","Penché sur le jeu ; un bol de pierres près du genou."],["La silhouette accroupie","Elle regarde depuis la gauche ; peut-être le bûcheron de la légende."],["Fruits et jarre","Un plat et une jarre au-delà du tablier."],["Signature et sceaux","Une signature et deux sceaux rouges en haut à droite."]]},"reise":{"title":"Le voyage autour du monde, par eau et par terre","artist":"Anonyme","date":"XIXe siècle","place":"Sans doute pays de langue allemande","game":"Jeu de parcours à un dé, avec mises","medium":"Lithographie","size":"42,5 × 33,7 cm","credit":"","p":["Une feuille de jeu titrée en allemand « Le voyage autour du monde, par eau et par terre : un nouveau et divertissant jeu de dés ». Un plateau rond porte les cases 1 à 41, illustrées d’un ballon, de voiliers, d’un vapeur, d’une locomotive, de gens de diverses nations, etc. Numéro « No. 107 » en bas à droite.","En dessous, la règle en allemand, anglais, néerlandais et français. Chacun verse d’abord 15 marks à la « caisse du voyage » commune, puis lance un dé à son tour et avance son pion. Tomber sur une grande image rapporte 2 marks, un numéro sans image coûte 2 marks d’amende, et qui atteint le 41 rafle le reste."],"spots":[["41 : la diligence","Le but au centre : une diligence avec voyageurs et cocher."],["1 : l’Anglais","La case de départ, « Engländer » en haut-de-forme."],["Le ballon","Une case avec un ballon dans le ciel."],["Le voilier","Un navire toutes voiles dehors."],["La locomotive","Une locomotive à vapeur fumante."],["La règle","La règle, imprimée en quatre langues."]]},"huchten":{"title":"Les dés pour la vie ou la mort","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Pays-Bas","game":"Dés","medium":"Huile sur toile","size":"67,5 × 76,0 cm","credit":"","p":["Œuvre du peintre hollandais Jan van Huchtenburg (1647–1733), connu pour ses batailles, signée en bas à gauche. Le titre du musée est « Le jeu de dés pour la vie ». Hors d’une forteresse, deux prisonniers jettent les dés sur un tambour, entourés d’officiers et de soldats.","Au fond à droite se dresse un gibet, et des soldats regardent depuis le rempart à gauche. Il s’agit sans doute de soldats condamnés tirant au sort aux dés celui qui sera exécuté. Un prisonnier montre le tambour ; l’autre, à genoux, regarde le coup."],"spots":[["Tambour et dés","Un tambour sert de table pour jeter les dés."],["Le prisonnier qui montre","Debout, il désigne le tambour."],["Le prisonnier à genoux","En chemise blanche, penché sur le tambour."],["L’officier à cheval","Coiffé d’un chapeau, il regarde du haut de sa monture."],["Le gibet","Le gibet, en haut à droite."],["Soldats sur le rempart","Des soldats qui regardent du haut du mur."]]},"vertu":{"title":"Le jeu de la vertu (Spel der Deugd)","artist":"Jan Gerritsz. Visser (d’après J. Voorman)","date":"1798","place":"Pays-Bas","game":"Jeu d’argent à deux dés","medium":"Gravure au burin, eau-forte et typographie","size":"56,9 × 38,0 cm","credit":"","p":["Une grande feuille de jeu titrée en néerlandais et en français « Le jeu de la vertu ». Dans un temple à colonnes trône la Vertu, avec la Prospérité à gauche et la Pauvreté à droite. Des médaillons de vertus — Sincérité, Gratitude, Amour… — ornent les colonnes, et les socles montrent des vices comme l’Avarice, l’Orgueil et la Paresse.","Selon la règle du bas, on joue avec deux dés ou en tirant des billets. Aux dés, les joueurs misent 63 en tout puis jettent à tour de rôle dans le sens du soleil. Chaque coup désigne une vertu ou un vice : le double six, la Vertu, prend la cagnotte, et le double as, le Vice, paie huit. Sous chaque image, « T » indique ce qu’on tire et « B » ce qu’on paie."],"spots":[["Le titre","« SPEL DER DEUGD » au fronton."],["La Vertu","La Vertu trônant au centre ; le double six prend tout."],["La Prospérité","La Prospérité et sa corne d’abondance."],["Le Vice","Le double as, le Vice : un enfant levant une coupe."],["L’Avarice","L’Avarice sur le socle ; « B » et les dés disent ce qu’on paie."],["La règle","La règle, imprimée serrée en bas."]]},"charros":{"title":"Les charros contrebandiers : jeu de dés","artist":"José Guadalupe Posada","date":"Non daté","place":"Mexique","game":"Jeu de parcours à trois dés","medium":"Lithographie","size":"29,9 × 40,4 cm","credit":"","p":["Un jeu de parcours illustré par Posada, intitulé « LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS » (Les charros contrebandiers / Jeu de dés). En bas, la mention de l’imprimerie A. Vanegas Arroyo, Mexico ; Posada a signé en bas à droite. Les charros, cavaliers mexicains, galopent en sombrero dans les coins.","Des cases rondes bordées de corde serpentent sur tout le plateau, peuplées d’animaux, de personnages, d’un train, etc. L’« Explication » en haut à droite dit qu’on joue avec trois dés. Trois as au premier coup gagnent ; tomber sur la tête de mort perd ; le cerf fait toucher la cagnotte, les voleurs font payer, et le lion immobilise jusqu’à ce qu’un autre vienne."],"spots":[["Le titre","« LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS »."],["L’explication","La règle, sous « EXPLICACION »."],["Les joueurs","Des gens autour d’une table, jouant sur un plateau, en bas à gauche."],["Les dés","Trois dés dessinés au milieu du plateau."],["Le charro à cheval","Un charro au galop qui fait tournoyer son lasso."],["L’imprimeur","« IMPRENTA DE A. VANEGAS ARROYO, MÉXICO »."]]},"snuffwq":{"title":"Tabatière à décor de joueurs de weiqi","artist":"Chine","date":"Dynastie Qing, marque et époque Daoguang (1820–50)","place":"Chine","game":"Weiqi (go)","medium":"Porcelaine à décor d’émaux sur couverte","size":"Haut. 5,7 cm","credit":"","p":["Un petit flacon où l’on portait le tabac à priser dans la Chine des Qing. Selon la notice du musée, il porte une marque du règne Daoguang et date de 1820–50. Sur sa panse de porcelaine blanche, haute d’environ six centimètres, un paysage de montagne et des personnages sont peints aux émaux.","Près d’un rocher en grotte, deux vieillards sont assis devant un goban posé sur un support bleu ; celui de gauche va poser une pierre. Derrière lui, un enfant tenant un bâton regarde. Le sujet évoque sans doute le bûcheron qui regarda jouer les immortels."],"spots":[["Le goban","Un tablier sur support bleu, finement quadrillé."],["Le vieillard barbu","En robe violette, il tend la main vers le jeu."],["Le vieillard d’en face","Assis à droite, la main levée."],["L’enfant au bâton","Il regarde par-derrière."],["La grotte","Un rocher en forme de grotte."],["Le bouchon","Un bouchon vert."]]},"ostade":{"title":"Joueurs de trictrac dans une auberge","artist":"Adriaen van Ostade","date":"1653","place":"Pays-Bas (Haarlem)","game":"Trictrac","medium":"Eau-forte","size":"8,5 × 7,4 cm","credit":"","p":["Une eau-forte grande comme la paume, du peintre de Haarlem Ostade, connu pour ses scènes paysannes, signée « A. ostade » en bas. Dans une auberge sombre, la lumière d’une fenêtre à plombs éclaire les personnages.","À la table de gauche, deux hommes s’affrontent au trictrac tandis qu’un troisième regarde par-derrière. À droite, un homme adossé au mur tient un gobelet. Une grosse cruche gît au sol ; on dirait un après-midi paresseux à l’auberge."],"spots":[["Le tablier","Un trictrac posé sur la table."],["Le joueur de gauche","Un homme coiffé d’un chapeau face au jeu."],["Le joueur de droite","Penché sur le jeu."],["Le curieux","Un homme debout derrière, qui regarde."],["L’homme au repos","Assis contre le mur, gobelet en main."],["La fenêtre à plombs","Une fenêtre à losanges, d’où vient la lumière."]]},"lenain":{"title":"Les joueurs de dés","artist":"Suiveur de Mathieu Le Nain","date":"1630–1680","place":"France","game":"Dés","medium":"Huile sur toile","size":"92,8 × 119,7 cm","credit":"","p":["Œuvre d’un suiveur de Mathieu, le cadet des frères Le Nain. Le musée signale qu’une esquisse d’une composition semblable, par Gabriel de Saint-Aubin, est conservée à la Bibliothèque nationale à Paris.","Trois hommes entourent une petite table ronde en plein air et jettent les dés ; deux autres regardent, celui de gauche serrant une bouteille. À droite, deux lévriers élancés ; au-delà, un vaste paysage. Les petites taches blanches sur la table sont les dés."],"spots":[["Les dés","Des dés sur la table ronde."],["L’homme au chapeau clair","Assis, il tend la main vers le coup."],["L’homme en noir","Un jeune homme debout, poing sur la hanche."],["Le garçon derrière","Il suit la partie derrière la table."],["L’homme à la bouteille","À gauche, il nous sourit."],["Les deux lévriers","Des chiens élancés à droite."]]},"tunisie":{"title":"Partie de cartes devant un café arabe (section tunisienne, Exposition d’Anvers)","artist":"Anonyme (impr. Ch. Bernhoeft)","date":"1894","place":"Belgique (Anvers)","game":"Cartes","medium":"Phototypie","size":"15,4 × 21,6 cm","credit":"","p":["Planche d’une série de 49 sur l’Exposition universelle d’Anvers de 1894, portant « EXPOSITION UNIVERSELLE D’ANVERS 1894 » en haut et « Tunisie. Partie de cartes devant un café arabe » en bas. Elle fut imprimée par Bernhoeft, photographe de la Cour à Luxembourg.","La vue est prise sur une place à coupoles et minaret, bâtie pour la section tunisienne de l’exposition. Des hommes en costume tunisien jouent aux cartes autour de petites tables carrelées ; l’un fume le narguilé, et un plateau de tasses est posé près d’eux. À droite, des visiteurs en costume : sans doute une mise en scène de la vie d’un pays lointain."],"spots":[["La table de jeu","Des hommes, cartes en main, autour d’une table carrelée."],["Le narguilé","Le tuyau du narguilé de l’homme de gauche."],["Les visiteurs","Des hommes en costume assis à droite, sans doute des visiteurs."],["Le plateau de tasses","De petites tasses sous la table."],["Coupoles et minaret","Les bâtiments de style tunisien construits pour l’exposition."],["La légende","« TUNISIE » et « PARTIE DE CARTES DEVANT UN CAFÉ ARABE »."]]},"laghouat":{"title":"Caïds des environs de Laghouat","artist":"Anonyme","date":"1880–1890","place":"Algérie (environs de Laghouat)","game":"Sans doute les dominos","medium":"Tirage sur papier albuminé","size":"20,9 × 27,0 cm","credit":"","p":["Une photographie intitulée « Types algériens. Caïds des environs de Laghouat », collée dans un album et portant le numéro « 239 ». Le caïd était un chef local dans l’Algérie sous domination française.","Des hommes en burnous blancs, assis sur une natte devant un mur de terre, alignent de longues pièces sur une table basse. À leur disposition, il s’agit sans doute de dominos, même si la notice du musée dit seulement « un jeu ». Devant, un plateau à thé et les babouches retirées."],"spots":[["Les pièces sur la table basse","De longues pièces alignées sur la table."],["Le plateau à thé","Verres et théière sur un plateau, devant."],["Les babouches","Les chaussures laissées près de la natte."],["La silhouette debout","Quelqu’un debout près du mur, qui regarde."],["Le mur de terre","Le mur de terre rugueux à l’arrière."],["La natte","La natte tressée où ils sont assis."]]},"hangong":{"title":"Dames du palais (Matin de printemps au palais des Han), détail","artist":"Copie d’après Qiu Ying","date":"Dynastie Qing (1644–1911)","place":"Chine","game":"Weiqi (go)","medium":"Rouleau horizontal ; encre et couleurs sur soie","size":"36,2 × 454,4 cm (rouleau entier)","credit":"","p":["Un détail d’un rouleau horizontal de plus de quatre mètres et demi, copie d’époque Qing d’une composition du peintre Ming Qiu Ying (1494–1552). Dans un palais, un jour de printemps, dames, jeunes filles et servantes se balancent, jouent, admirent les pivoines, font de la musique, jouent du qin, nourrissent un perroquet et des poissons.","Dans cette scène, deux femmes se font face devant un goban derrière une balustrade, et d’autres se penchent pour regarder. Devant, une pierre de lettré dans une vasque en forme de lotus ; des servantes portent instruments et paquets. Comme le note le musée, le rouleau idéalise la vie des femmes dans les appartements intérieurs."],"spots":[["Le goban","Un goban sur une table derrière la balustrade."],["La joueuse qui pose une pierre","Une femme en mauve tendant la main vers le jeu."],["Les spectatrices","Des femmes penchées sur la partie."],["La dame à l’éventail","Une femme tenant un éventail rond entre les piliers."],["La pierre de lettré","Un rocher bleu dans une vasque en lotus."],["La servante à l’instrument","Une servante portant ce qui est sans doute un pipa."]]},"homerbg":{"title":"Backgammon","artist":"Winslow Homer","date":"v. 1877","place":"États-Unis","game":"Backgammon","medium":"Gravure sur bois de bout","size":"","credit":"","p":["Une gravure sur bois d’après un dessin du peintre américain Winslow Homer (1836–1910), qui dessina dans sa jeunesse de nombreuses illustrations pour ce genre d’estampes. En bas est imprimé « 396.—BACKGAMMON.—WINSLOW HOMER. » : sans doute une planche numérotée d’un livre ou d’une revue.","Deux femmes assises face à face sur un canapé orné jouent au backgammon sur un tablier posé en travers de leurs genoux. Un objet rond et blanc repose sur le jeu, sans qu’on sache ce que c’est. Les plis des longues jupes et les accoudoirs en volute sont taillés en traits fins."],"spots":[["Le tablier","Le jeu posé sur les genoux des deux femmes."],["La femme de gauche","Cheveux relevés, elle tend la main vers le jeu."],["La femme de droite","Penchée pour étudier la partie."],["L’accoudoir","Un accoudoir en volute."],["Les jupes","De longues jupes aux plis finement taillés."],["La légende","« 396.—BACKGAMMON.—WINSLOW HOMER. » en bas."]]},"chessst":{"title":"Homme et femme jouant aux échecs (vue stéréoscopique)","artist":"Anonyme","date":"1852–1858","place":"Inconnu","game":"Échecs","medium":"Vue stéréoscopique coloriée","size":"8,3 × 16,5 cm","credit":"","p":["Une paire de photographies montées en vue stéréoscopique, connue en anglais sous le titre « The Chess Players ». Au stéréoscope, l’échiquier et les pièces semblent sortir en relief. La couleur a été ajoutée sur l’image en noir et blanc, au rideau rouge et à la robe jaune.","La femme en jaune a la main sur une pièce, tandis que l’homme en face, vu de dos, étudie la position. Pièces rouges et blanches sont en pleine partie, mais la scène a sans doute été arrangée en atelier. Ces vues de scènes domestiques se vendaient en masse au milieu du XIXe siècle."],"spots":[["L’échiquier","Pièces rouges et blanches sur l’échiquier."],["La main qui joue","La main de la femme sur une pièce."],["La femme","En robe jaune à col blanc, penchée sur le jeu."],["L’homme","Assis de dos."],["Le rideau rouge","Le rideau colorié du fond."],["La seconde image","La vue de droite ; au stéréoscope, la paire prend du relief."]]},"corrida":{"title":"Jeu de dés de la corrida (Corrida de Toros)","artist":"José Guadalupe Posada","date":"1898","place":"Mexique","game":"Jeu de parcours à deux dés, avec mises","medium":"Similigravure en relief sur papier vélin","size":"40,4 × 30,0 cm","credit":"","p":["Un jeu de parcours illustré par Posada, intitulé « CORRIDA DE TOROS ». Les cases s’enroulent en spirale et montrent dans l’ordre les passes et les moments de la corrida, de la case 1 à l’extérieur jusqu’au centre. Au milieu, des arènes ; en bas, le nom de l’imprimerie d’Antonio Vanegas Arroyo.","Selon l’« Explication » du bas, deux joueurs ou plus misent chacun puis avancent en lançant deux dés. Le 5, « saut à la perche », mène au 10 ; le 12, « coup de corne au picador », fait payer et passer son tour ; le 28, « passe de poitrine », renvoie au départ. Qui atteint le 32, « l’arrastre du taureau », rafle toutes les mises."],"spots":[["Le titre","Les mots « CORRIDA DE TOROS »."],["Les arènes","Le bâtiment des arènes au cœur de la spirale."],["La case 1","Le départ, à l’entrée de la spirale."],["La tête de taureau","Une tête de taureau cornue en haut à droite."],["Le torero","Le portrait d’un torero en bas à gauche."],["L’explication","L’« EXPLICACION » imprimée en pied."]]},"ambrocards":{"title":"Trois hommes jouant aux cartes","artist":"Auteur inconnu (américain)","date":"1865","place":"États-Unis","game":"Cartes","medium":"Ambrotype","size":"14,0 × 11,0 cm","credit":"","p":["L’ambrotype est un négatif léger sur verre, doublé de noir pour paraître positif. Moins cher que le daguerréotype, il fut très répandu en Amérique dans les années 1850–60. Celui-ci se trouve derrière un passe-partout doré, dans un étui tapissé de velours rouge.","Devant un fond uni, trois hommes entourent une petite table, leurs cartes en main. Celui de gauche porte un melon, celui de droite une casquette, tous deux le cigare aux lèvres ; celui du centre, en veste sombre, nous regarde. Ils ont sans doute posé comme en pleine partie pour l’appareil."],"spots":[["Les mains","Des mains tenant les cartes au-dessus de la table."],["L’homme au melon","À gauche, cigare aux lèvres."],["L’homme du centre","En veste sombre, il nous regarde."],["L’homme à la casquette","À droite, cigare aux lèvres."],["Le passe-partout doré","Le cadre doré estampé autour de l’image."],["L’étui","L’étui tapissé de velours rouge."]]},"morphy":{"title":"Paul Morphy, le champion d’échecs","artist":"Winslow Homer","date":"1859","place":"États-Unis","game":"Échecs","medium":"Gravure sur bois de bout","size":"","credit":"","p":["Un portrait gravé sur bois portant « PAUL MORPHY, THE CHESS CHAMPION », d’après un dessin de Winslow Homer (1836–1910), alors jeune illustrateur. Morphy (1837–1884), de La Nouvelle-Orléans, parcourut l’Europe en 1858–59 en battant un maître après l’autre, et rentra célèbre.","Le jeune Morphy, assis, pose la main gauche au bord d’un échiquier, près d’un roi, d’une tour, de pions et d’autres pièces. Fait en 1859, à son retour triomphal, il fut sans doute imprimé comme illustration dans un journal ou une revue."],"spots":[["Les pièces","Un roi, une tour, des pions et d’autres sur l’échiquier."],["La main sur l’échiquier","Sa main gauche au bord du plateau."],["Le visage de Morphy","Le champion, à peine vingt ans passés."],["Le nœud papillon","Un col soigné."],["La main sur le genou","Sa main droite posée sur le genou."],["Le titre","« PAUL MORPHY, THE CHESS CHAMPION » en bas."]]},"dutton":{"title":"La famille Dutton dans le salon de Sherborne Park, Gloucestershire","artist":"Johann Zoffany","date":"v. 1772","place":"Angleterre","game":"Cartes","medium":"Huile sur toile","size":"101,5 × 127,0 cm","credit":"","p":["Œuvre de Johann Zoffany (1733–1810), peintre né en Allemagne qui fit carrière en Angleterre. La « conversation piece », portrait de famille informel, naquit dans l’Angleterre du XVIIIe siècle et connut une grande vogue. La scène se passe dans le salon de Sherborne Park, dans le Gloucestershire.","Selon le musée, le père et la fille, la mère et le fils réfléchissent au prochain coup d’une partie de cartes. La famille venait de perdre un proche : les parents portent le grand deuil en noir, les enfants le demi-deuil en mauve, blanc et gris."],"spots":[["La table de jeu","Une table au tapis vert et des cartes."],["Le père","En noir, ses cartes en main."],["La fille","En blanc, regardant son jeu."],["Le fils","En gris, ses cartes en main."],["La mère","En grand deuil noir."],["La cheminée","Une cheminée de marbre où brûle un feu."]]},"whist":{"title":"Les universitaires de Noël : partie combinée de whist","artist":"James Bretherton (probablement d’après H. W. Bunbury)","date":"1773","place":"Angleterre","game":"Whist (cartes)","medium":"Eau-forte","size":"26,5 × 39,6 cm","credit":"","p":["Selon le musée, une satire des universitaires de Cambridge. En bas à gauche on semble lire « H. W. Bunbury del. 1772 » et à droite « J. Bretherton f. » ; la feuille fut publiée en 1773 par une boutique de New Bond Street, à Londres. Des bonnets carrés pendent au mur.","Quatre messieurs jouent au whist en se faisant des grimaces. Le whist se joue à deux équipes de deux : la « partie combinée » du titre est sans doute un jeu de mots. Derrière, un homme fait des cornes avec ses doigts au-dessus de la tête d’un autre. Deux serviteurs et deux chiens sont là."],"spots":[["Les cartes","Des cartes jouées sur la table."],["L’universitaire à perruque","Un savant en grande perruque, son jeu contre lui."],["Le geste des doigts","Un homme derrière lève les doigts au-dessus d’une tête."],["La servante","Une domestique en chapeau, un plateau à la main."],["Les bonnets carrés","Des bonnets d’université au mur."],["Le chien de droite","Un petit chien qui aboie en bas à droite."]]},"hey":{"title":"Trois hommes jouant aux échecs","artist":"Paul Hey","date":"1877–1952","place":"Allemagne","game":"Échecs","medium":"Estampe (sans doute eau-forte)","size":"19,3 × 26,0 cm","credit":"","p":["Une estampe du peintre et illustrateur allemand Paul Hey (1867–1952). Trois hommes âgés se penchent sur un même échiquier ; de fines lignes superposées dessinent leurs rides et leurs barbes blanches.","Comme l’indique la notice du musée, l’homme de gauche a la main au menton, et celui de droite tient un cigare en tendant la main vers les pièces. À gauche de la table, deux tasses de café, un verre et une boîte d’allumettes. Sans doute une partie au café."],"spots":[["L’échiquier","Échiquier et pièces sur la table."],["L’homme main au menton","Barbe blanche, plongé dans ses pensées."],["L’homme du milieu","Penché, il tend la main vers une pièce."],["L’homme de droite","Il regarde par-derrière."],["La main au cigare","Un cigare entre les doigts."],["Café et allumettes","Deux tasses, un verre et une boîte d’allumettes à gauche."]]},"artful":{"title":"La carte rusée, ou une de trop pour grand-mère. Cœur est atout !","artist":"Anonyme","date":"1852–1863","place":"Sans doute Grande-Bretagne","game":"Cartes","medium":"Vue stéréoscopique coloriée","size":"8,4 × 17,4 cm","credit":"","p":["Le titre anglais est « The artful card, or, one too many for granny. Hearts are trumps! ». Une petite scène comique où l’on roule grand-mère avec une carte rusée, montée en paire de photographies stéréoscopiques. D’après le titre anglais, elle a sans doute été faite en Grande-Bretagne.","À une table ronde, la grand-mère et une fillette jouent aux cartes, tandis que la jeune femme en vert, son jeu en main, est enlacée par un jeune homme derrière elle. « Cœur est atout » joue sans doute sur la couleur et sur l’amour. La pièce au rouet et au vaisselier est sûrement un décor d’atelier."],"spots":[["Le jeu de la jeune femme","Les cartes que tient la jeune femme en vert."],["Le jeune homme","La main sur son épaule, derrière elle."],["La grand-mère","Une vieille femme en fichu, les yeux sur ses cartes."],["La fillette","Elle sourit en jouant une carte."],["La table","Une table ronde avec cartes et menus objets."],["Le vaisselier","Un meuble vitré garni de vaisselle."]]},"cezcards":{"title":"Étude pour Les Joueurs de cartes","artist":"Paul Cézanne","date":"1890–92","place":"France","game":"Cartes","medium":"Aquarelle et mine de plomb sur vélin beige","size":"36,2 × 48,5 cm","credit":"","p":["Dans les années 1890, à Aix, Cézanne peignit plusieurs tableaux d’hommes jouant aux cartes. Voici une aquarelle préparatoire pour cette série : un homme moustachu, coiffé d’un chapeau, assis à une table, regarde son jeu.","Sur le tracé à la mine de plomb, de légers lavis bleus et gris saisissent les plis de la veste et le poids du corps. La droite et le bout de la table restent inachevés ; la couleur n’est posée qu’autour de la figure. Ses modèles auraient été des travailleurs du pays."],"spots":[["Le visage","Les yeux baissés sous le chapeau, il regarde ses cartes."],["Les cartes","Des cartes tenues des deux mains."],["La table","Une table seulement tracée au crayon."],["La chaise","Le dossier de la chaise, à gauche."],["La veste","Des plis construits en bleu et gris."],["L’inachevé","Près des pieds de la table, il ne reste que les traits."]]},"vuillardck":{"title":"La Partie de dames, de Paysages et intérieurs","artist":"Édouard Vuillard","date":"1899","place":"France","game":"Dames","medium":"Lithographie en couleurs sur chine gris-ivoire","size":"36,9 × 28,5 cm","credit":"","p":["La première planche de Paysages et intérieurs, album de lithographies en couleurs du peintre Vuillard, publié par le marchand Ambroise Vollard et tiré par l’imprimeur lithographe Auguste Clot.","Dans une pièce saturée de papier peint, un homme barbu est assis devant un damier, tandis qu’une femme en robe à carreaux, debout, la main au menton, regarde. Figures, papier peint et canapé se fondent en aplats et motifs ; seules les cases noires et blanches du damier ressortent nettement."],"spots":[["Le damier","Le damier noir et blanc."],["L’homme barbu","Assis devant le jeu."],["La femme debout","En robe à carreaux, la main au menton."],["Le papier peint","Un papier couvert de lignes tourbillonnantes."],["Le coussin fleuri","Une étoffe à motifs en bas à gauche."],["La lampe","Une forme élancée de lampe contre le mur."]]},"cruikchess":{"title":"Partie d’échecs","artist":"George Cruikshank, d’après le capitaine Frederick Marryat","date":"1814","place":"Angleterre","game":"Échecs","medium":"Eau-forte coloriée à la main","size":"23,8 × 34,5 cm","credit":"","p":["Une estampe du caricaturiste anglais Cruikshank d’après un croquis de Marryat, officier de marine puis romancier, publiée à Londres par Hannah Humphrey. Le titre « GAME of CHESS » court en bas.","À une table éclairée de bougies, deux vieux messieurs s’affrontent aux échecs. Derrière chacun se tient un spectateur : celui de gauche porte un doigt à ses lèvres, celui de droite scrute l’échiquier à travers un face-à-main. Sans doute une moquerie des spectateurs qui ne savent pas se taire."],"spots":[["L’échiquier","L’échiquier et ses pièces noires et blanches."],["Les bougies","Deux bougies éclairant le jeu."],["L’homme qui fait chut","Un spectateur, un doigt sur les lèvres."],["L’homme au face-à-main","Un spectateur qui scrute le jeu."],["Le chien endormi","Un chien qui dort sous la table."],["Le titre","« GAME of CHESS » en bas."]]},"domino98":{"title":"Femme et enfant jouant aux dominos à une table","artist":"Auteur inconnu (américain)","date":"v. 1898","place":"États-Unis","game":"Dominos","medium":"Tirage albuminé contrecollé sur verre","size":"40,8 × 51,1 cm","credit":"","p":["Une grande photographie, sans doute d’un atelier américain, achevée en la collant sur verre. Une femme en blanc et une fillette aux cheveux bouclés sont assises de part et d’autre d’une petite table fleurie.","Des dominos sont posés sur la table, et la femme en place un. La fillette, le menton dans la main, regarde. Rideaux, meuble chargé et tableaux au mur sont sans doute un décor d’atelier."],"spots":[["Les dominos","Des dominos blancs alignés sur la table."],["La fillette","Le menton dans la main, elle regarde."],["La femme","En blanc, elle pose un domino."],["Les fleurs","Un vase de fleurs sur la table."],["Le meuble","Un meuble orné au fond à droite."],["L’inscription","Des lettres blanches en bas à droite."]]},"langkat":{"title":"Albert Glaser jouant aux cartes avec deux amis sur un bateau, Langkat, Sumatra","artist":"Anonyme (H. Ernst & Co.)","date":"1895–1905","place":"Indonésie (Langkat, Sumatra)","game":"Cartes","medium":"Photographie","size":"17,5 × 22,8 cm","credit":"","p":["Une photographie prise à Langkat, dans le nord de Sumatra. En bas à droite figure le timbre sec de l’atelier « H. Ernst & Co. / Bindjey Langkat », et au dos une note manuscrite indique que l’homme du milieu est Albert Glaser, frère d’une dame.","Sur le pont d’un bateau, sous un auvent, trois hommes en blanc sont attablés, cartes en main. Sur la table, des cartes et de petites pièces semblables à des jetons, et une bouteille près de l’homme de droite. Les habits blancs et l’auvent disent la vie sous un climat chaud."],"spots":[["Sur la table","Cartes distribuées et petites pièces."],["Glaser","L’homme du milieu déploie son jeu ; la note du dos le nomme."],["L’homme de gauche","Vu à demi de dos, cartes en main."],["L’homme de droite","Moustachu, cartes en main."],["La bouteille","Une bouteille près de l’homme de droite."],["L’auvent","Des feuillages pendus à l’auvent."]]},"chatur":{"title":"Une partie de chaturanga","artist":"Anonyme","date":"1805–1815","place":"Inde","game":"Chaturanga","medium":"Gouache et or, pinceau","size":"16,2 × 9,8 cm (image)","credit":"","p":["Une miniature indienne. Selon la notice du musée, deux femmes jouent au chaturanga, un jeu de plateau, tandis qu’une servante tient un chasse-mouches. Le chaturanga, vieux jeu indien, passe pour l’ancêtre des échecs.","Sous des arcs blancs, sur un tapis rouge, une femme en bleu sombre et une femme en orange se font face devant un plateau quadrillé. Celle en orange tend la main comme si elle parlait. L’image est encadrée d’une bordure rouge sombre filetée de noir et de blanc."],"spots":[["Le plateau","Un plateau quadrillé sur le tapis rouge."],["La femme en bleu","Parée d’or, elle tend la main vers le jeu."],["La femme en orange","En face, la main tendue."],["La servante","Debout derrière."],["Le chasse-mouches","Brandi par la servante."],["La bordure rouge","Un cadre rouge sombre fileté de noir et de blanc."]]},"shabbarat":{"title":"Soirée dans les appartements des femmes","artist":"Anonyme","date":"1760–1770","place":"Inde","game":"Chaupar (pachisi)","medium":"Gouache et or, pinceau","size":"34,3 × 25,6 cm","credit":"","p":["Une miniature indienne. Selon la notice du musée, quatre femmes jouent à un jeu de plateau dans la vaste cour d’un palais, le chaupar ou pachisi. Elles sont assises autour d’un plateau de tissu en forme de croix.","La femme au premier plan à droite tient trois dés allongés, prête à les jeter. À côté, appuyée sur un traversin, se trouve la dame de plus haut rang. C’est la nuit, mais des lampes éclairent partout la terrasse et d’innombrables lumières bordent les murs lointains de la ville. La notice suppose qu’on célèbre la fête musulmane de Shab-i-Barat."],"spots":[["Le plateau en croix","Le plateau cruciforme étalé au sol."],["La joueuse aux dés","Au premier plan, les dés allongés en main."],["La dame au traversin","La dame de plus haut rang."],["La servante","Elle approche avec un plateau."],["Une lampe","Une bougie sous une cloche de verre."],["Le pavillon lointain","Un jardin à fontaine, un pavillon et les lumières de la ville."]]},"govase":{"title":"Vase ovoïde aux femmes jouant au go","artist":"Anonyme (sceau « Tang Jintang »)","date":"1724","place":"Chine (Guangdong)","game":"Go (weiqi)","medium":"Porcelaine aux émaux sur couverte et dorure","size":"Hauteur 15,3 cm","credit":"","p":["Un vase chinois en porcelaine très fine, peint aux émaux. Au dos, une inscription : « image d’une partie de go, peinte le jour de la fête des Fleurs de l’année jiachen, dans une agréable maison au bord de la rivière des Perles, au Lingnan », avec le sceau rouge « Tang Jintang ». Il appartenait à la collection de porcelaines du collectionneur haguenois Jean Theodore Royer.","Deux femmes se font face devant un goban posé sur une table ; celle de gauche tient un bol de pierres. À droite, deux femmes et deux enfants se penchent pour regarder. Sur le meuble derrière, des antiquités, dont un vase aux plumes de paon et du corail."],"spots":[["Le goban","Un goban sur la table, aux pierres blanches et noires."],["La joueuse de gauche","Un bol de pierres en main, elle désigne le jeu."],["La joueuse de droite","Penchée sur le goban."],["Les spectatrices","Des femmes qui regardent par-derrière."],["Plumes de paon et corail","Dans un vase sur le meuble."],["Le bol de pierres","Tenu par la femme de gauche."]]},"yokihi":{"title":"Un homme jouant au backgammon avec une dame (l’empereur Xuanzong et Yang Guifei)","artist":"Anonyme (surimono)","date":"1822","place":"Japon","game":"Ban-sugoroku (backgammon japonais)","medium":"Gravure sur bois en couleurs, pigments métalliques","size":"21,6 × 19,1 cm","credit":"","p":["Un surimono, estampe de luxe associant image et poésie, imprimée sur papier épais avec des poudres métalliques et commandée par des poètes comme cadeau. Celle-ci porte un poème et le nom du poète, Tachibana no Goen.","Selon la notice du musée, l’empereur Tang Xuanzong (685–762) joue au sugoroku avec sa concubine favorite Yang Guifei (719–756) ; ce jeu est parent du backgammon et du trictrac. Des pions blancs et noirs se dressent sur un plateau en forme de boîte posé sur un support rouge."],"spots":[["Le plateau","Un plateau de sugoroku en boîte sur un support rouge."],["Yang Guifei","Des fleurs dans les cheveux, la main sur le jeu."],["Xuanzong","La main au menton, il regarde le jeu."],["Le poème","Un poème et le nom du poète en haut à gauche."],["Le paravent","Un paravent peint de montagnes, derrière."],["Signature et sceau","Une signature et un sceau rouge en bas à droite."]]},"disderi":{"title":"Hommes en costume de marin jouant aux cartes","artist":"Disdéri & Cie","date":"1850–1890","place":"France (Paris)","game":"Cartes","medium":"Tirage albuminé (carte de visite)","size":"8,6 × 5,3 cm","credit":"","p":["Une carte de visite photographique provenant d’un album, portant au dos « Disdéri & Cie, 8 boulevard des Italiens, Paris ». Disdéri est le photographe qui popularisa la carte de visite, petits portraits tirés en nombre comme des cartes de visite.","Des hommes vêtus à l’ancienne — tricorne, longue veste, bas blancs — jouent aux cartes autour d’une table ornée. La notice du musée parle d’un costume de marin, mais il s’agit sans doute d’un costume de théâtre ou de bal masqué. L’homme du milieu se lève pour regarder la table."],"spots":[["La table","Une table à bordure ornée, avec cartes et gobelets."],["L’homme debout","En tricorne, il se penche sur la table."],["L’homme de gauche","Assis, cartes en main."],["L’homme de droite","En tricorne, cartes en main."],["Souliers à boucle","Bas blancs et souliers à boucle."],["Le cadre doré","La bordure dorée du carton."]]},"gans":{"title":"Jeu de l’oie (spirale de 74 cases)","artist":"Jan Oortman (père), d’après Daniel Willem Stoopendaal","date":"1763–1823","place":"Pays-Bas","game":"Jeu de l’oie (jeu de parcours)","medium":"Gravure sur bois coloriée en bleu, rouge et vert","size":"40,8 × 46,8 cm","credit":"","p":["Un parcours en spirale imprimé aux Pays-Bas. Selon le musée, les cases vont de 1 à 74, certaines illustrées. Jan Oortman a gravé le bois d’après un dessin de Stoopendaal, dont le nom figure en bas à droite avec « invenit ».","Le but, le 74, est un temple au bord de la mer au soleil couchant, au centre. Des cases portent des mots comme « LEER GELD » (prix de l’apprentissage), « DWAALWEG » (fausse route) ou « DOMHEID / WYSHEID » (sottise / sagesse), et un squelette à la faux, « EINDE » (la fin) : sans doute un jeu moral sur le chemin de la vie."],"spots":[["74 : le temple","Le but : un temple au rivage, au couchant."],["1 : le départ","La première case, en bas à gauche."],["Le prix","Une case « LEER GELD », sans doute où l’on paie."],["La fausse route","Un chemin de bois marqué « DWAALWEG »."],["La fin","Un squelette à la faux : « EINDE »."],["Les dés","Une case avec deux dés."]]},"merelle":{"title":"La merelle et le cerf-volant","artist":"Claudine Stella, d’après Jacques Stella","date":"1657","place":"France (Paris)","game":"Merelle (jeu du moulin)","medium":"Gravure au burin","size":"11,7 × 14,1 cm","credit":"","p":["Planche 17 d’une suite de jeux d’enfants gravée par Claudine Stella d’après les dessins de son oncle, le peintre Jacques Stella. Selon le musée, elle provient d’un album de 51 gravures. Les joueurs sont de petits enfants nus et potelés, des putti.","Devant à gauche, ils jouent à la merelle sur un tablier tracé dans un bloc de pierre. Au sol, à droite, les lignes du franc du carreau, où l’on lance des pièces sur les carreaux ; plus loin, un enfant court avec un cerf-volant. Les vers dessous disent que chacun prend peine à bien jouer."],"spots":[["La marelle du moulin","Un tablier gravé dans la pierre, avec ses pions."],["Le cerf-volant","Un cerf-volant haut dans le ciel."],["L’enfant au cerf-volant","Il court, la ficelle en main."],["Le franc du carreau","Carrés et diagonales tracés au sol."],["L’enfant qui montre","Un objet en main, il désigne les lignes."],["Le titre","« LA MERELLE, & LE CERF VOLANT »."]]},"feldcards":{"title":"Partie de cartes à une table de jardin (vue stéréoscopique)","artist":"Anonyme","date":"1850–1880","place":"Inconnu (cachet d’une maison de Groningue au dos)","game":"Cartes","medium":"Tirage albuminé (vue stéréoscopique)","size":"8,5 × 17,0 cm","credit":"","p":["Une vue stéréoscopique d’une famille ou d’amis jouant aux cartes à une table de jardin, devant un treillage couvert de lierre. Au dos figure le cachet de Feldbrugge & Co., à Groningue (Pays-Bas), sans doute le magasin ou l’éditeur qui la vendait.","L’homme barbu à gauche lève haut une carte, prêt à l’abattre sur la table. Un homme la tête dans la main, un garçon et ses cartes, un vieillard aux cheveux blancs et une femme qui regarde derrière complètent l’instant. Comme il fallait rester immobile, la scène a sans doute été posée."],"spots":[["La carte levée","La carte brandie par le barbu."],["Sur la table","Les cartes déjà jouées."],["Le jeu du garçon","Les cartes du garçon vu de dos."],["Le vieillard","L’homme aux cheveux blancs assis à droite."],["La femme qui regarde","Debout derrière, elle suit la partie."],["La chaise brodée","Une chaise garnie d’étoffe fleurie, au premier plan."]]},"tempel":{"title":"Plateau de jeu « Le Temple de la fortune »","artist":"Anonyme","date":"1816","place":"Pays-Bas","game":"Jeu de parcours aux dés","medium":"Gravure sur bois et texte typographié","size":"43,0 × 48,5 cm","credit":"","p":["Une feuille de jeu dont les cases 1 à 74 s’enroulent en spirale. Au centre, un temple rond au bord de la mer ; la règle conservée dans la même collection l’appelle « Le Temple de la fortune » et parle d’un jeu de lancer, c’est-à-dire de dés.","La plupart des cases sont des cercles vides, mais çà et là figurent roses, épines, dés, grille, bac et autres images, ainsi que des mots comme « LEER GELD » (frais d’apprentissage), « DOMHEID » (sottise) et « WYSHEID » (sagesse). Sans doute un jeu moral qui passe par vertus et défauts jusqu’au temple."],"spots":[["Le Temple de la fortune","Le temple au bord de la mer, au centre : la case 74, le but."],["La case 1","Le départ, en bas à gauche."],["Frais d’apprentissage","Une case marquée « LEER GELD »."],["Les dés","Deux dés dessinés dans la rangée du haut."],["Le bac","L’image « OVER HAAL » (passage) en bas."],["Sottise et sagesse","Les mots « DOMHEID » et « WYSHEID » à droite."]]},"verkeer":{"title":"Tablier miniature de verkeer","artist":"Anonyme","date":"1690–1710","place":"Pays-Bas (Amsterdam)","game":"Verkeer (parent du trictrac), échecs, marelle","medium":"Noyer marqueté d’olivier, d’ébène, de buis et d’os ; ferrures de cuivre","size":"Fermé 5,8 × 5,8 cm (ouvert 11,6 cm)","credit":"","p":["Un tablier à peine large de six centimètres, qui s’ouvre comme une boîte. À l’extérieur, un échiquier et une marelle ; à l’intérieur, un jeu de verkeer, cousin néerlandais du trictrac. Il se ferme par des charnières de cuivre et un minuscule crochet.","Il contient encore un dé, neuf pions d’os, quatre d’ébène et trois petites pièces de monnaie. Son numéro d’inventaire indique qu’il fait sans doute partie du mobilier de la maison de poupée de Petronella Oortman. Si petit soit-il, sa marqueterie est soignée et construite comme un vrai tablier."],"spots":[["Le dé","Un dé pas plus gros qu’un grain de riz."],["Les pions d’os","Des pions ronds en os blanc."],["Les pions d’ébène","Des pions noirs en ébène."],["Les flèches","Des triangles marquetés de bois clair et foncé."],["Les charnières","Des charnières de cuivre pour le plier."],["Le crochet","Un minuscule crochet de cuivre pour le fermer."]]},"silverbd":{"title":"Damier miniature en argent avec ses pions","artist":"Frederik van Strant II","date":"1739","place":"Pays-Bas (Amsterdam)","game":"Dames, marelle","medium":"Argent","size":"5,4 × 5,4 cm","credit":"","p":["Un damier d’argent de 5,4 centimètres de côté seulement : 64 cases, un rebord et un anneau de suspension. Les cases foncées sont gravées de fines hachures, et l’autre face porte les lignes de la marelle.","Il est poinçonné de la marque d’Amsterdam, de la lettre-date E pour 1739 et du poinçon de l’orfèvre Frederik van Strant II. Quinze pions l’accompagnent, huit ornés d’une fleur et sept d’un cercle. Sans doute une miniature d’argent pour une maison de poupée ou une vitrine."],"spots":[["Pions à fleur","Des pions frappés d’une fleur."],["Pions à cercle","Des pions marqués d’un cercle."],["L’anneau","Un anneau à l’angle du damier."],["Cases gravées","Des cases foncées finement hachurées."],["Cases lisses","Des cases claires, lisses et polies."],["Le rebord","Le bord relevé tout autour."]]},"schaak1550":{"title":"Jeu d’échecs à pièces équestres","artist":"Anonyme","date":"1550","place":"Allemagne","game":"Échecs","medium":"Buis et bois de conifère","size":"Pièce la plus haute 10,5 cm","credit":"","p":["Chaque pièce se dresse sur un piédouche tourné entouré d’une balustrade de fleurons, sculpté de cavaliers et de chevaux. Rois et reines montent chevaux ou mules, comme partant à la chasse.","Selon la notice du musée, le roi noir monte un cheval cabré foulant un dragon et porte au cou une chaîne évoquant l’ordre de la Toison d’or, peut-être pour en faire Charles Quint. Une reine chevauche en amazone une mule, un faucon au poing. À droite, une pièce comique montre un singe sur le dos d’un homme."],"spots":[["Le roi","Un roi couronné et barbu, à cheval."],["La reine","Une reine en amazone sur une mule, faucon au poing."],["La pièce au singe","Un singe sur le dos d’un homme."],["Une pièce comique","À gauche, un homme juché sur un autre."],["Les créatures","Dragons et bêtes sous les sabots."],["Les piédouches","Des piédouches tournés à fleurons."]]},"kraaij":{"title":"Hommes et femmes jouant à un jeu de plateau dans un salon","artist":"Anonyme","date":"1900–1910","place":"Sans doute Pays-Bas","game":"Backgammon (trictrac)","medium":"Tirage au collodion à noircissement direct","size":"8,0 × 11,1 cm","credit":"","p":["Une page d’un album de famille qui contient aussi des photos des négociants en vin Kraaij & Co., Bordeaux–Amsterdam. Dans un salon éclairé d’un lustre, hommes et femmes, sans doute famille et amis, entourent une table.","Sur la table s’ouvre un tablier en forme de coffret pliant, et les femmes de chaque côté tiennent un cornet à dés. La notice du musée dit « un jeu de plateau », mais le coffret et les cornets désignent sans doute le backgammon. Des tasses à café et une cage à oiseau au fond évoquent une soirée paisible."],"spots":[["Le coffret-plateau","Un coffret pliant ouvert en plateau."],["Le cornet de gauche","Celui de la femme à lunettes."],["Le cornet de droite","La femme en robe à pois s’apprête à jeter."],["La cage","Une cage à oiseau sur un guéridon, au fond."],["Le lustre","Des lampes à globes de verre suspendues."],["L’homme debout","À droite, il regarde la partie."]]},"braekel":{"title":"Vieil homme et vieille femme jouant aux dames","artist":"Ferdinand De Braekeleer (I)","date":"1862","place":"Belgique (Anvers)","game":"Dames","medium":"Eau-forte","size":"21,8 × 16,5 cm","credit":"","p":["Une eau-forte du peintre anversois De Braekeleer (1792–1883), signée en bas à gauche « Ferdinand De Braekeleer Antwerpen 1862 ». Dans une vieille cuisine à cheminée, un vieil homme et une vieille femme sont assis de part et d’autre d’une petite table.","Des pions ronds sont sur le damier ; lui en saisit un tandis qu’elle ouvre la main comme pour répliquer. Un chapeau est posé par terre, avec quelques pions tombés. Des assiettes garnissent l’étagère, et l’on voit des maisons par la fenêtre."],"spots":[["Damier et pions","Le damier et les pions ronds sur la table."],["Le vieil homme","Penché, il saisit un pion."],["La vieille femme","Coiffée d’un capuchon, elle parle en gesticulant."],["Le chapeau","Le chapeau du vieil homme posé au sol."],["La signature","« Ferdinand De Braekeleer Antwerpen 1862 »."],["Les assiettes","De grands plats sur l’étagère de la cheminée."]]},"billiard":{"title":"Le billard","artist":"D’après H. W. Bunbury (graveur anonyme)","date":"1780","place":"Angleterre (Londres)","game":"Billard","medium":"Eau-forte et pointillé","size":"30,0 × 39,1 cm","credit":"","p":["Une estampe d’après le caricaturiste anglais Henry William Bunbury, publiée à Londres en 1780 par Watson & Dickinson. Selon le musée, c’est la quatrième d’une suite.","Deux hommes jouent au billard tandis que les autres regardent, le souffle coupé. L’un se penche sur la table pour jouer ; un autre porte sa queue sur l’épaule. Un râtelier à queues et deux cadrans ronds de marque ornent le mur. Le musée note que la table paraît triangulaire."],"spots":[["Table et billes","La table drapée et ses billes."],["Le joueur qui vise","Penché sur la table pour jouer."],["L’homme à la queue","Il attend, sa longue queue en main."],["Les cadrans","Deux cadrans au mur, sans doute pour marquer les points."],["Le râtelier","Une rangée de queues contre le mur."],["Les deux rieurs","Deux spectateurs à droite, qui rient ensemble."]]},"baizi":{"title":"Cent enfants (détail)","artist":"Xu Yanghong","date":"XVIIIe siècle","place":"Chine","game":"Weiqi (go)","medium":"Rouleau horizontal ; encre (et couleurs légères) sur papier","size":"29,8 × 526 cm (rouleau entier)","credit":"","p":["Une scène de go tirée d’un rouleau de plus de cinq mètres du peintre professionnel chinois Xu Yanghong. Dans un jardin, cent enfants jouent, font de la musique, lisent et écrivent. Les « cent enfants » sont un grand thème de l’art asiatique, symbole de fécondité et de prospérité familiale.","Le rouleau est aussi connu par une copie du maître japonais Tani Bunchō, conservée au même musée. Près de feuilles de bananier et d’une pierre de lettré, des enfants entourent un goban sur un support bas ; deux jouent, bol de pierres en main, les autres regardent."],"spots":[["Le goban","Un goban sur un support bas, avec ses pierres."],["L’enfant qui joue","En veste bleue, la main dans le bol de pierres."],["L’autre joueur","En blanc, penché sur le jeu."],["Mains derrière la tête","Un enfant qui regarde par-derrière."],["La pierre de lettré","Un grand rocher percé de trous."],["L’éventail de plumes","Un enfant à gauche avec un éventail de plumes."]]},"schenkcards":{"title":"Deux Chinoises jouant aux cartes","artist":"Pieter Schenk (II)","date":"1727–1775","place":"Pays-Bas (sujet : la Chine)","game":"Cartes","medium":"Eau-forte","size":"16,5 × 26,2 cm","credit":"","p":["Une planche de la première partie des « Chinois nouvellement inventés », recueil de figures et paysages à la chinoise publié par le graveur et éditeur amstellodamois Pieter Schenk le Jeune. C’est une chinoiserie, goût d’une Chine rêvée alors à la mode en Europe.","Selon la notice du musée, deux Chinoises jouent aux cartes dans un jardin, tandis qu’une femme arrive à droite avec un plateau garni. Les cartes sur la table ressemblent à des cartes européennes. À gauche, un lapin repose sur un support ; un voilier flotte sur la rivière."],"spots":[["Les cartes","Des cartes étalées ; elles semblent européennes."],["La femme de gauche","Cartes en main, elle regarde sa partenaire."],["La femme de droite","Elle pose une carte."],["La femme au plateau","Elle apporte un plateau garni."],["Le lapin","Sur un support, à gauche."],["Le voilier","Un bateau sur la rivière."]]},"gosaucer":{"title":"Soucoupe aux joueurs de go","artist":"Anonyme","date":"1725–1735","place":"Chine","game":"Go (weiqi)","medium":"Porcelaine aux émaux sur couverte et dorure","size":"Diamètre 16,4 cm","credit":"","p":["Une soucoupe chinoise peinte dans les doux émaux de la famille rose. Dessous, une marque : un pinceau, un sceptre ruyi et un bâton d’encre dans un double cercle. Les notices du musée décrivent les personnages tantôt comme un homme et une femme jouant au go, tantôt comme trois femmes dont deux jouent.","Un goban est posé sur une table dans une pièce ; deux joueurs face à face posent leurs pierres, un troisième regarde debout derrière. Sur la table, des bols jaunes ; derrière, un support portant un vase de fleurs, et à droite une grande jarre bleue."],"spots":[["Le goban","Un goban et ses pierres sur la table."],["Le joueur de gauche","En mauve pâle, accoudé à la table."],["Le joueur de droite","En rose, posant une pierre."],["Le spectateur","Debout derrière, il regarde."],["Le vase","Un vase de fleurs sur un support."],["La jarre bleue","Une grande jarre à droite."]]},"cheetham":{"title":"Une petite partie de cartes (en Russie)","artist":"Anonyme","date":"1903–1904","place":"Russie","game":"Cartes","medium":"Tirage gélatino-argentique à noircissement direct","size":"9,2 × 11,5 cm","credit":"","p":["Tirée de l’album de la famille anglaise Cheetham, qui vécut en Russie ; le carton porte en anglais « a little card-party ». Le musée indique qu’il s’agit sans doute d’amis anglais venus voir Joseph Cheetham.","Dans une pièce tapissée, trois personnes sont attablées devant une nappe fleurie, leurs cartes en éventail. Deux bougeoirs se dressent sur la table, et la femme au milieu rit en déployant son jeu. Sans doute un moment détendu entre compatriotes, loin de chez eux."],"spots":[["Le jeu de l’homme de gauche","Les cartes du barbu."],["Le jeu de la femme","La femme du milieu ouvre ses cartes en éventail."],["L’homme de droite","Penché en avant, cartes en main."],["Les bougeoirs","Deux bougeoirs sur la table."],["La nappe","Une grande nappe à fleurs et motifs."],["L’inscription","« a little card-party » sur le carton."]]},"problem":{"title":"Le problème (vue stéréoscopique)","artist":"Anonyme","date":"1852–1863","place":"Inconnu","game":"Échecs","medium":"Vue stéréoscopique coloriée","size":"8,4 × 17,4 cm","credit":"","p":["Le titre anglais est « The Problem ». Deux personnages en perruque blanche et costume du XVIIIe siècle jouent aux échecs à une table ouvragée, en paire de photographies stéréoscopiques coloriées. Au dos est écrit à la main « Simons ».","Le plus jeune se tient les joues à deux mains, les yeux rivés sur l’échiquier, tandis que l’aîné en face sourit malicieusement. Sans doute une scène théâtrale arrangée, où l’on voit d’un coup d’œil qui a le problème. Un chien est couché à leurs pieds."],"spots":[["L’échiquier","L’échiquier et les pièces sur la table ouvragée."],["Le joueur perplexe","La tête dans les mains, il fixe le jeu."],["L’homme qui sourit","L’aîné en habit bleu, souriant."],["Le chien","Un chien couché à leurs pieds."],["Le rideau rouge","Le rideau colorié du fond."],["La seconde image","La vue de droite ; au stéréoscope, elle prend du relief."]]},"tarocco":{"title":"Dix cartes d’un jeu de tarot","artist":"Anonyme (sans doute d’après Giuseppe Maria Mitelli)","date":"1660–1718","place":"Italie (Bologne)","game":"Tarocchi (jeux de cartes à atouts)","medium":"Eau-forte et burin, en partie coloriés à la main en brun clair","size":"Dix cartes sur un montage","credit":"","p":["Dix cartes d’un jeu de tarot bolonais, collées côte à côte sur un support. Le tarot servit d’abord non à la divination, mais à des jeux de cartes à atouts. En haut à gauche, une carte de titre ; le musée suggère que son portrait pourrait être celui de l’artiste Mitelli.","La rangée du haut montre quatre figures, dont un homme couronné et un cavalier ; celle du bas, du six au dix de deniers, chaque carte portant autant de pièces que son numéro. Les traits gravés sont en partie lavés de brun clair."],"spots":[["La carte de titre","En haut à gauche : un portrait encadré et une inscription."],["L’homme couronné","Une figure couronnée tenant un sceptre."],["La femme debout","Une femme couronnée tenant une coupe."],["Le cavalier","Une carte avec un personnage à cheval."],["Dix de deniers","En bas à gauche : dix pièces."],["Six de deniers","En bas à droite : six pièces."]]},"kindtegel":{"title":"Carreaux à scènes de jeux d’enfants","artist":"Anonyme","date":"1680–1730","place":"Pays-Bas","game":"Jeux d’enfants (échasses, balançoire…)","medium":"Faïence (carreaux de Delft), peinte en bleu","size":"107 × 80 cm (48 carreaux)","credit":"","p":["Un champ de quarante-huit carreaux, huit de haut sur six de large. Chacun montre deux enfants qui jouent, peints en petit en bleu, avec dans chaque coin un ornement appelé « araignée ».","L’un marche sur des échasses, un autre se fait pousser sur une balançoire, d’autres sont accroupis sur quelque chose au sol : chaque carreau montre un jeu différent. Ces carreaux de « jeux d’enfants » étaient très appréciés aux Pays-Bas et garnissaient sans doute les murs des cuisines et le tour des cheminées."],"spots":[["Les échasses","Un enfant sur des échasses."],["La balançoire","Un enfant poussé sur une balançoire."],["Un jeu au sol","Des enfants accroupis jouant avec quelque chose au sol."],["Les araignées","Les petits ornements des coins."],["Quarante-huit carreaux","Huit rangées de six carreaux."],["Le dernier carreau","Le carreau du coin inférieur droit."]]},"dammolen":{"title":"Damier miniature pour les dames et la marelle","artist":"Anonyme","date":"1740–1760","place":"Pays-Bas (Amsterdam)","game":"Dames, marelle (jeu du moulin)","medium":"Noyer et pâte de remplissage claire","size":"4,2 × 4,0 × 1,5 cm","credit":"","p":["Un minuscule plateau de noyer d’environ quatre centimètres. Presque carré, à rebord, il sert d’un côté de damier et de l’autre de jeu de marelle.","Côté dames, les cases ont été creusées puis remplies d’une pâte claire pour former le damier sur le bois nu ; côté marelle, les lignes gravées sont comblées de la même pâte. Si petit, il était sans doute destiné à une maison de poupée."],"spots":[["Cases remplies","Cases creusées et comblées de pâte claire."],["Cases de bois","Cases laissées en noyer nu."],["Le rebord","Le bord relevé tout autour."],["L’angle proche","L’angle le plus proche."],["L’épaisseur","Le chant du plateau, 1,5 cm."],["Le rang du fond","La rangée de cases du fond."]]},"karelpiece":{"title":"Pion de dames au portrait de Charlemagne (moitié)","artist":"Anonyme","date":"1525–1575","place":"Allemagne (Nuremberg)","game":"Dames ou trictrac","medium":"Buis","size":"Diamètre 5,3 cm","credit":"","p":["Une face d’un pion de dames sculpté dans le buis. Au centre, un profil dans une couronne de laurier ; autour, l’inscription « CAROLVS. MAGNVS. IMPER. AVGVST. » (Charlemagne, empereur).","Le musée en conserve plus d’une douzaine du même type, chacun portant un empereur ou une impératrice de la Rome antique au Moyen Âge : Tibère, Agrippine, Louis le Pieux, Otton, etc. Sans doute un jeu de luxe conçu comme une galerie de souverains."],"spots":[["Le profil","Le profil de Charlemagne dans une couronne de laurier."],["La couronne","L’anneau de laurier autour du portrait."],["CAROLVS","Les mots « CAROLVS. MAGNVS » en haut."],["AVGVST","Les mots « IMPER. AVGVST » à gauche."],["L’étoile","Une petite étoile séparant l’inscription."],["Le bord","Le bord à ressaut du pion."]]},"vdberge":{"title":"Le jeu hollandais, la belle vie ! (Jeu de cartes)","artist":"Pieter van den Berge (invention et édition)","date":"1694–1737","place":"Pays-Bas (Amsterdam)","game":"Cartes","medium":"Eau-forte imprimée à la poupée en rouge, bleu et vert","size":"27,3 × 17,0 cm","credit":"","p":["Une satire du graveur et éditeur amstellodamois Van den Berge, intitulée « LE JEU HOLLANDOIS. LA BELLE VIE ! ». Selon le musée, des hommes jouent aux cartes dans une taverne tandis que des diables, près d’un homme qui soupire en levant son verre et sous la table, lui gagnent son argent.","Dans les vers néerlandais du bas, le viveur insouciant se plaint que combats de chiens et de coqs, cartes et dés ont fait fondre son argent. De part et d’autre, deux diables l’invitent en allemand à s’amuser aux dés et aux cartes. Le tableau du fond montre aussi des combats de chiens et de coqs."],"spots":[["L’homme au verre","Le viveur en grande perruque lève son verre."],["Le jeu en main","Des cartes déployées dans sa main."],["Le diable de gauche","Un diable ricanant derrière lui."],["Le diable sous la table","Il ramasse les pièces tombées au sol."],["Le tableau des combats","Une peinture de combats de chiens et de coqs."],["Titre et vers","« LE JEU HOLLANDOIS » et la plainte du viveur."]]},"crespi":{"title":"Enfants jouant aux dés","artist":"Giuseppe Maria Crespi","date":"1675–1747","place":"Italie","game":"Dés","medium":"Eau-forte","size":"22,5 × 15,1 cm","credit":"","p":["Une eau-forte du peintre bolonais Crespi, gravée de sa main. Selon le musée, quatre enfants jouent aux dés dans la rue, et trois vers italiens sont ajoutés en dessous.","Un enfant accroupi vient de jeter les dés par terre tandis que les trois autres regardent. Les vers parlent d’os (les dés), de nombres, d’un jeu bref et d’argent qui diminue : sans doute une mise en garde contre le jeu, même pour un amusement d’enfants."],"spots":[["Les dés","De petits dés à terre."],["L’enfant accroupi","Il vient de jeter les dés."],["L’enfant debout","Penché sur le coup."],["L’enfant de droite","Assis par terre, il regarde."],["L’enfant derrière","Il passe la tête derrière les autres."],["Les vers","Trois vers italiens."]]},"epinal":{"title":"Grand jeu de l’oie (Épinal)","artist":"Pellerin & Cie (Épinal)","date":"1791–1900","place":"France (Épinal)","game":"Jeu de l’oie","medium":"Gravure sur bois coloriée en jaune, rouge, vert et bleu ; texte typographié","size":"39,8 × 59,0 cm","credit":"","p":["Une feuille en couleurs de l’imagerie Pellerin d’Épinal, titrée en français « GRAND JEU DE L’OIE ». Selon le musée, une spirale de 63 cases montre des oies, d’autres animaux et des personnages, avec au centre le titre néerlandais « GANZENBORD ! » et la règle.","D’après la règle, on jette deux dés, et tomber sur une oie fait avancer d’autant. Le pont du 6 mène au 12, l’auberge du 19 coûte deux tours, au puits (31) on attend qu’un autre vienne, le labyrinthe (42) renvoie au 30 et la mort (58) au départ. Il faut atteindre le 63 juste pour gagner. Des jetons à découper bordent les deux côtés."],"spots":[["63 : l’oie","Le but, le 63 : une oie sur un étang."],["La règle","La règle néerlandaise au centre."],["Jetons à découper","Jetons ronds numérotés de chaque côté."],["Le titre","« GRAND JEU DE L’OIE » en haut."],["Enfants qui jouent","Des enfants dans le coin inférieur gauche."],["L’éditeur","« PELLERIN & Cie » en haut à gauche."]]},"matham":{"title":"Couple jouant au trictrac","artist":"Jacob Matham (éditeur), vers de Simon Sovius","date":"1621","place":"Pays-Bas (Haarlem)","game":"Trictrac","medium":"Gravure au burin","size":"17,9 × 20,0 cm","credit":"","p":["La troisième estampe d’une suite de quatre publiée par le graveur et éditeur de Haarlem Matham. Selon le musée, un couple élégamment vêtu joue au trictrac pour de l’argent à une petite table ; la bourse est posée sur la table et la dame tient les dés.","Les longues flèches et les dames claires et sombres du tablier sont nettement gravées. Dessous, des vers latins et néerlandais : les néerlandais avertissent que l’excès de boisson n’éveille pas seul des pensées impures, mais que le jeu et les dés vont contre tout profit. Derrière, un garçon lève un verre de vin."],"spots":[["Le tablier","Un trictrac avec ses flèches et ses dames."],["L’homme qui joue","Coiffé d’un chapeau, il tend la main vers le jeu."],["La dame aux dés","Grande fraise au cou, elle tient les dés."],["Le garçon au verre","Il lève un verre de vin derrière eux."],["La bourse","La bourse des mises sur la table."],["Les vers","Des vers d’avertissement en latin et en néerlandais."]]},"jardin":{"title":"Trois hommes jouant aux cartes à une table de jardin, avec un spectateur (France)","artist":"Anonyme (photographe amateur français)","date":"1900–1910","place":"France","game":"Cartes","medium":"Tirage sur papier albuminé","size":"11,8 × 17,2 cm","credit":"","p":["Tirée de l’album d’un photographe amateur français, qui contient aussi des vues d’une famille, de la distillerie Delizy & Doistau, de l’armée et de curiosités de France.","À l’ombre d’un jardin gravillonné, trois hommes jouent aux cartes à une petite table, tandis qu’un homme âgé à barbe blanche regarde debout derrière eux. Des cartes sont sur la table et l’homme au canotier examine son jeu. Sans doute un moment détendu en famille ou entre amis."],"spots":[["Les cartes sur la table","Les cartes jouées."],["Le spectateur","L’homme âgé à barbe blanche, debout derrière."],["L’homme au canotier","Au milieu, il examine son jeu."],["L’homme de droite","En veste sombre, cartes en main."],["L’homme de gauche","En veste claire."],["Le jardin","Gravier et massifs du jardin."]]},"lamplight":{"title":"Personnes jouant aux cartes (sous la lampe)","artist":"Anonyme","date":"1900–1910","place":"Inconnu","game":"Cartes","medium":"Tirage gélatino-argentique","size":"7,5 × 10,0 cm","credit":"","p":["Une petite photographie d’album, que le musée intitule « Personnes jouant aux cartes ». Ni le photographe ni le lieu ne sont connus.","À la lumière d’une lampe à pétrole suspendue, une femme en robe rayée, une fillette et des garçons sont attablés devant une nappe à franges, leurs cartes en éventail. Photographier dans une pièce sombre devait être difficile ; sans doute voulait-on saisir une veillée familiale."],"spots":[["La nappe à franges","Une nappe imprimée à franges."],["La lampe","Une lampe à pétrole suspendue."],["La femme en rayures","Assise en robe blanche rayée."],["Le jeu de la femme","Les cartes qu’elle tient en éventail."],["Le jeu de la fillette","La fillette du milieu étale son jeu."],["Le garçon de droite","Penché, cartes en main."]]},"borduur":{"title":"Plateau brodé de table de jeu avec une partie de cartes","artist":"Anonyme","date":"1700–1725","place":"Inconnu","game":"Cartes","medium":"Gros point et petit point en laine et soie de couleurs","size":"100 × 185 cm","credit":"","p":["Broderie du plateau d’une table de jeu pliante, en laine et soie polychromes, alternant gros point et petit point. Dans une forme à pans coupés court un cadre de volutes et de fleurs.","Dans le paysage central, deux dames et un gentilhomme jouent aux cartes autour d’une table. Selon la notice du musée, une bourse, des cartes et d’autres accessoires de jeu y sont posés. Une table à jouer ornée, fort à propos, d’une partie de cartes."],"spots":[["La table","La table verte avec bourse et cartes."],["Le gentilhomme","Un homme coiffé d’un chapeau, à gauche."],["La dame du centre","Une dame assise derrière la table."],["La dame de droite","Une dame vêtue de bleu."],["Les arbres","Des arbres derrière les figures."],["Le cadre","Un cadre de volutes et de fleurs."]]},"piquet":{"title":"Tapis imprimé d’un jeu de piquet","artist":"Anonyme","date":"1725–1750","place":"Inconnu","game":"Piquet (jeu de cartes)","medium":"Lin imprimé en rouge et violet","size":"73,0 × 82,5 cm","credit":"","p":["Un tapis de lin pour table de jeu, imprimé en rouge et violet des accessoires d’une partie de cartes. La notice du musée le décrit aussi comme un mouchoir.","Des cartes de piquet — jeu de 32 cartes du sept à l’as — sont semées sur la bordure et au centre, avec une bourse au milieu et des jetons autour. Les figures sont au portrait de Paris, avec des noms comme César, Argine et Hogier."],"spots":[["La bourse","La bourse des enjeux, au centre."],["Les figures","Rois et dames au portrait de Paris."],["Les jetons","Des jetons ronds."],["La bordure de cartes","Une bande de cartes autour du tapis."],["Les jeux retournés","Des paquets montrant leur dos."],["Le paquet scellé","Un paquet de cartes cacheté, en bas à droite."]]},"schaakglas":{"title":"Verre gravé de deux joueurs d’échecs","artist":"Anonyme","date":"1815–1830","place":"Inconnu","game":"Échecs","medium":"Verre incolore, gravé à la roue","size":"Haut. 13,7 cm","credit":"","p":["Un verre à pied transparent, dont l’image et le texte ont été gravés à la petite roue. À une table éclairée de deux bougies, deux hommes s’affrontent devant un échiquier.","Celui de gauche, à lunettes, fume la pipe ; celui de droite se penche sur le jeu, et un verre de vin est posé sur la table. Tout autour : « Savoir la marche, est Chose très unie / Savoir le Jeu, c’est Fruit du genie »."],"spots":[["L’échiquier","L’échiquier et ses pièces."],["L’homme à la pipe","À gauche, à lunettes, la pipe aux lèvres."],["L’homme penché","À droite, scrutant le jeu."],["Les bougies","Deux bougies derrière l’échiquier."],["Le verre de vin","Un verre sur la table."],["L’inscription","Le texte gravé en français."]]},"arlequin":{"title":"Le jeu de loto d’Arlequin","artist":"Anonyme (édité par Mindermann & Co.)","date":"1818–1845","place":"Pays-Bas (Amsterdam)","game":"Loto / jeu de parcours","medium":"Gravure coloriée à la main, collée sur carton","size":"Inconnu","credit":"","p":["Une feuille de jeu dont le plateau est Arlequin lui-même, debout jambes écartées. Des cases carrées numérotées de 1 à 32 courent sur son costume vert et entre ses jambes. En bas, le titre « Arlequin’s Lotto-Spel » et le nom de Mindermann & Co., à Amsterdam.","Il porte un masque de résille et tient un chapeau et ce qui ressemble à une batte de bois. Certaines cases portent « HW » ou « P ». La gravure coloriée a été collée sur carton, sans doute pour servir de plateau."],"spots":[["Le masque de résille","La résille qui couvre son visage."],["La case 1","Le départ, sous sa jambe gauche."],["Une case HW","Une case marquée « HW »."],["P 32","La case 32, marquée « P »."],["Le titre","« Arlequin’s Lotto-Spel » en bas."],["Le chapeau","Le chapeau dans sa main droite."]]},"vicaire":{"title":"La partie du vicaire","artist":"René Gayant (d’après la planche)","date":"1888–1893","place":"France","game":"Cartes","medium":"Phototypie (d’après le musée)","size":"10,4 × 15,6 cm","credit":"","p":["Une planche du Bulletin du Photo-Club de Paris, intitulée « La partie du Vicaire ». La marge porte « Phototype René Gayant » et « Héliogravure Lemercier » : la photographie est donc sans doute de Gayant, l’impression de Lemercier. Elle était reliée de travers dans le volume.","Dans une cuisine garnie de casseroles, un prêtre en soutane noire, attablé, examine ses cartes, et l’homme en face tient aussi un jeu. Un homme en casquette a le menton dans la main, et un jeune, la main à l’oreille, suit la partie. La lumière et la composition de tableau conviennent à un club voué à la photographie artistique."],"spots":[["Le jeu du vicaire","Les cartes qu’examine le prêtre."],["Le vicaire","En soutane noire et col blanc."],["L’homme aux cartes","Les cheveux bouclés, il regarde son jeu."],["Le jeune spectateur","La main à la joue, il suit la partie."],["L’homme à la casquette","Le menton dans la main."],["Le mur de la cuisine","Casseroles et louches accrochées."]]},"israels":{"title":"Les joueurs d’échecs","artist":"Isaac Israels","date":"1875–1922","place":"Pays-Bas","game":"Échecs","medium":"Pastel","size":"40,0 × 57,5 cm","credit":"","p":["Un pastel du peintre néerlandais Isaac Israels (1865–1934), connu pour ses scènes vives et rapides de la vie urbaine à Amsterdam. Dans une pièce à la fenêtre claire, des hommes entourent un échiquier.","Les deux du premier plan ont la joue ou le menton dans la main et fixent l’échiquier, tandis qu’un homme en casquette se penche derrière eux. Les pièces ne sont pas détaillées mais posées en touches de couleur ; un long moment de réflexion semble s’écouler."],"spots":[["L’échiquier","L’échiquier ; les pièces sont des touches de couleur."],["Le joueur de gauche","La joue dans la main, il regarde le jeu."],["Le joueur de droite","Le menton dans la main, il réfléchit."],["L’homme en casquette","Il se penche par-derrière."],["La fenêtre","La fenêtre claire à gauche."],["La chaise","Une chaise à droite."]]},"louisxi":{"title":"Louis XI et sa fille Anne de Beaujeu","artist":"Adrien Joseph Verhoeven-Ball","date":"1866","place":"Belgique (Anvers)","game":"Échecs","medium":"Estampe (sans doute eau-forte)","size":"26,4 × 31,3 cm","credit":"","p":["Le peintre anversois Verhoeven-Ball a dessiné et gravé lui-même cette estampe (« pinx et sculp », en bas). Le titre du musée est « Louis XI et sa fille Anne de Beaujeu jouent aux échecs ». Une ligne mentionne la 2e exposition de l’Association des artistes anversois.","Louis XI, roi de France au XVe siècle, est assis à la table en robe fourrée, tandis que sa fille Anne, le menton dans la main, étudie l’échiquier. Des pièces et une coupe de fruits sont sur la table, un chien dort au sol et un garde armé se tient derrière. Sans doute une scène imaginée du père et de la fille historiques."],"spots":[["Échiquier et pièces","L’échiquier et les pièces sur la table."],["Louis XI","Le roi en chapeau et robe fourrée."],["Anne","Sa fille, le menton dans la main."],["Le chien endormi","Un chien élancé allongé au sol."],["Le garde","Un soldat armé dans l’ombre."],["Le titre","« LOUIS XI ET SA FILLE ANNE DE BEAU-JEU »."]]},"bruining":{"title":"Moines jouant aux dames","artist":"Tieleman Cato Bruining","date":"1750–1850","place":"Pays-Bas","game":"Dames","medium":"Eau-forte","size":"20,6 × 16,8 cm","credit":"","p":["Une eau-forte du graveur néerlandais Bruining, inscrite en bas à gauche « T. Bruining inv. et fecit aqua fort » (inventé et gravé à l’eau-forte). Selon le musée, deux moines jouent aux dames à une table.","Derrière eux se tiennent un troisième moine et un diable en froc. Près de la table se dresse la Mort, elle aussi déguisée en moine, la faux cachée dans le dos. Les moines sont si absorbés par la partie qu’ils ne remarquent pas les intrus."],"spots":[["Le damier","Le damier et les pions sur la table."],["La Mort","En froc, la faux cachée dans le dos."],["Les deux derrière","Un troisième moine et le diable en froc."],["Le joueur de gauche","Un moine penché sur le damier."],["Le joueur de droite","Un moine qui réfléchit, les bras sur la table."],["La signature","« T. Bruining inv. et fecit aqua fort »."]]},"vanvliet":{"title":"Joueurs de trictrac à la chandelle","artist":"Jan Gillisz. van Vliet","date":"1631–1634","place":"Pays-Bas (Leyde)","game":"Trictrac","medium":"Eau-forte et burin","size":"15,2 × 13,4 cm","credit":"","p":["Une estampe de Van Vliet, qui travaillait à Leyde aux côtés de Rembrandt. Selon le musée, deux personnages jouent au trictrac dans une pièce sombre avec un lit à baldaquin à gauche, et un homme et une femme se tiennent à droite.","Un homme en noir se penche très bas sur le tablier, de dos, tandis que son adversaire rit, la main sur le bord du jeu. Flèches et dames se voient nettement. La source de lumière est cachée, mais seuls le jeu et les visages sont éclairés : sans doute une partie nocturne."],"spots":[["Le tablier","Un trictrac avec ses flèches et ses dames."],["Le joueur qui rit","La main sur le bord du jeu, il rit."],["L’homme penché","En noir, de dos, penché sur le jeu."],["L’homme au chapeau","Debout derrière, en chapeau à large bord."],["Le personnage à fraise","À droite, la main levée."],["Les rideaux du lit","Rideaux du lit à baldaquin à gauche."]]},"hermans":{"title":"Deux femmes et une fillette devant un échiquier","artist":"François Hermans (atelier)","date":"1857–1895","place":"Pays-Bas (Rotterdam)","game":"Échecs","medium":"Tirage albuminé (carte de visite)","size":"10,1 × 6,2 cm","credit":"","p":["Une carte de visite photographique provenant d’un album de famille, portant au dos le nom de l’atelier « François Hermans / Hang 421 / Rotterdam ». Sans doute un portrait-souvenir de famille pris en atelier.","Un échiquier est posé sur un petit guéridon ; la femme de gauche touche une pièce, celle de droite, la joue dans la main, réfléchit. Entre elles, une fillette debout nous regarde droit dans les yeux. Toutes trois ont dû rester immobiles pendant la longue pose."],"spots":[["L’échiquier","L’échiquier et les pièces sur le guéridon."],["La main qui joue","La femme de gauche touche une pièce."],["La fillette","Debout derrière l’échiquier, elle nous regarde."],["La femme pensive","La femme de droite, la joue dans la main."],["Le tabouret","Un tabouret rond sur le sol."],["La fenêtre","Une fenêtre à croisillons au fond à droite."]]},"norimberg":{"title":"Pion de dames à la vue de Nuremberg","artist":"Anonyme","date":"1690","place":"Allemagne (Nuremberg)","game":"Dames ou trictrac","medium":"Buis","size":"Diamètre 5,4 cm, épaisseur 1,5 cm","credit":"","p":["Un pion de buis sculpté en relief d’une vue de Nuremberg, avec ses tours et son château. En haut : « SVB AQVILAE ROMANAE ALIS QVIESCO » (je repose sous les ailes de l’aigle romaine) ; en bas : « NORIBERGA VRBIVM REGINA » (Nuremberg, reine des villes).","Selon la notice du musée, l’autre face porte les portraits de l’empereur Joseph Ier et des sept princes-électeurs. Sans doute la fierté de Nuremberg, ville impériale du Saint-Empire, gravée dans un pion."],"spots":[["La vue","Nuremberg, ses flèches et ses remparts."],["La devise du haut","« SVB AQVILAE ROMANAE… »."],["La devise du bas","« NORIBERGA VRBIVM REGINA »."],["L’emblème","Le petit emblème tout en haut."],["Le château","Le château sur la hauteur, à droite."],["Le bord","Le bord à ressaut du pion."]]},"toovenaar":{"title":"Le Magicien : nouveau jeu amusant pour enfants","artist":"Anonyme","date":"1856","place":"Pays-Bas (Amsterdam)","game":"Jeu de parcours (cousin du jeu de l’oie)","medium":"Lithographie avec texte typographié, coloriée à la main","size":"44,5 × 53,5 cm","credit":"","p":["Un jeu de parcours intitulé « DE TOOVENAAR » (Le magicien), « nouveau jeu amusant pour enfants », aux cases 1 à 63 en spirale. Au centre, un magicien devant une table avec crâne, calice, lune et étoiles, des êtres diaboliques derrière lui ; des diables à tête de bête occupent les coins.","La règle imprimée au centre ressemble fort à celle du jeu de l’oie. On lance deux dés : six et trois au premier coup mènent au 26, cinq et quatre au 53. Le magicien fait recompter comme une oie ; le pont coûte un, l’auberge deux et un tour, le labyrinthe du 42 fait reculer de trois, et la Mort fait payer et recommencer."],"spots":[["Le magicien","Le magicien devant sa table, au centre."],["Titre et règle","Le titre « DE TOOVENAAR » et la règle."],["Le but 63","La dernière case de la spirale."],["Les diables","Des diables à tête de bête dans les coins."],["Le parcours extérieur","Des cases illustrées tout autour du bord."],["La table","Crâne et calice sur la table."]]},"fichesdoos":{"title":"Boîte en ivoire à jetons","artist":"Mariaval le Jeune","date":"1725","place":"France (Paris)","game":"Jetons pour les jeux de cartes","medium":"Ivoire","size":"2 × 8 × 6 cm","credit":"","p":["Une boîte d’ivoire grande comme la paume, pour les jetons qui remplaçaient l’argent aux jeux de cartes. Sur le couvercle, une femme couronnée tenant un sceptre trône sur des nuages près d’un paon, avec deux armoiries ; avec son paon, c’est sans doute Junon.","Selon la notice du musée, le couvercle porte « Mariaval le Jeune a Rouen fecit », et le dessous un aigle et des oiseaux, dont l’un pendu à un gibet. Dedans restent dix-neuf grands et six petits jetons peints d’insectes et de fleurs."],"spots":[["La femme couronnée","Une femme couronnée assise sur des nuages."],["Le paon","Un paon à ses pieds."],["Les armoiries","Deux armoiries en haut à droite."],["L’oiselet","Un oiseau sur un perchoir près d’elle."],["Les nuages","Les nuages qui la portent."],["Le bord du couvercle","Le bord et le fermoir du couvercle."]]},"vuilmere":{"title":"La Mère de l’artiste jouant aux dames","artist":"Édouard Vuillard","date":"v. 1890–91","place":"France","game":"Dames","medium":"Pastel, mine de plomb, estompe et gommage sur vélin ivoire","size":"37,5 × 30,5 cm","credit":"","p":["Un pastel de Vuillard représentant sa mère. Le peintre vivait avec elle et dessina sans cesse des scènes de la maison où elle travaillait comme couturière. Signé « E Vuillard » en bas à droite.","Deux figures en noir sont assises de part et d’autre d’une table d’un orange éclatant ; celle du premier plan tient un damier. D’après le titre du musée, c’est la mère de l’artiste. Dans un ovale cerné de noir, personnes et meubles se fondent en masses de couleur et de forme."],"spots":[["Le damier","Un damier de cases noires et blanches."],["La figure du fond","Une figure en noir de l’autre côté de la table."],["La figure du premier plan","Celle qui tient le damier."],["La table orange","Un éclat de couleur dans l’image."],["Le mur à motifs","Un papier aux lignes tourbillonnantes."],["La signature","« E Vuillard » en bas à droite."]]},"dewitte":{"title":"Deux hommes jouant aux échecs","artist":"Adrien de Witte","date":"1877","place":"Belgique","game":"Échecs","medium":"Sans doute eau-forte","size":"13,2 × 12,5 cm","credit":"","p":["Une petite estampe du peintre et graveur liégeois de Witte (1850–1935). Selon le musée, la littérature (Clercx, 1981) suppose que les deux joueurs sont Terme et Zeyen.","À une table couverte d’un tapis, un jeune homme regarde l’échiquier les bras croisés, tandis que l’homme plus âgé en face appuie la tête dans sa main, pensif. Derrière l’échiquier, on voit ce qui semble être une boîte à pièces. Dans la pièce sombre aux fines hachures, une partie tranquille se déroule."],"spots":[["Échiquier et pièces","L’échiquier et les pièces sur la table."],["La boîte","Ce qui semble une boîte derrière l’échiquier."],["Le jeune homme","Bras croisés, il regarde le jeu."],["L’homme âgé","La tête dans la main, il réfléchit."],["Le tapis de table","L’étoffe sur la table."],["La chaise","Le dossier d’une chaise en bois courbé à gauche."]]},"orphans":{"title":"Les orphelins (enfants jouant aux dames)","artist":"Charles Rolls, d’après W. Gill","date":"1810–1834","place":"Angleterre","game":"Dames","medium":"Estampe (gravure au burin)","size":"22,6 × 13,9 cm","credit":"","p":["Une estampe titrée en bas « THE ORPHANS » (Les orphelins), portant « Painted by W. Gill, Engraved by C. Rolls ». Selon le musée, elle a peut-être servi dans The Keepsake, un livre-étrenne annuel publié à Londres.","Dans une cuisine, une fille et un garçon jouent aux dames sur un damier posé sur un tonneau. Derrière eux une femme brode, et au fond se trouve ce que le musée appelle un métier à tisser. Le titre laisse penser que ce sont des orphelins recueillis par la femme."],"spots":[["Le damier","Le damier et les pions sur un tonneau."],["La fille","Penchée sur le damier."],["Le garçon","Il déplace un pion."],["La brodeuse","Elle brode derrière eux."],["La cruche","Une cruche au sol."],["Le titre","« THE ORPHANS » en bas."]]},"richelieu":{"title":"Louis XIII et Richelieu","artist":"Jan Frederik Christiaan Reckleben","date":"1850","place":"Pays-Bas (Amsterdam)","game":"Échecs","medium":"Gravure sur acier","size":"24,2 × 29,6 cm","credit":"","p":["Une gravure sur acier de l’Amstellodamois Reckleben, portant en tête « 1850. NEDERLANDSCH MUSEUM. Pl. II. ». Selon le musée, elle illustrait peut-être un article de la revue Nederlandsch Museum.","Devant une grande cheminée, le roi Louis XIII et son ministre le cardinal de Richelieu jouent aux échecs sous les yeux d’un groupe d’hommes. Le cardinal, assis à gauche, tend la main vers une pièce ; le roi, en chapeau à plumes, se tient à l’aise. À l’extrême gauche, un moine croise les bras."],"spots":[["L’échiquier","Échiquier et pièces sur la table drapée."],["Richelieu","Le cardinal tend la main vers une pièce."],["Louis XIII","Le roi au chapeau à plumes."],["Le moine","Bras croisés, il regarde à gauche."],["Les courtisans","Des hommes réunis à droite."],["Le titre","« LODEWIJK DE XIII EN RICHELIEU » en bas."]]},"coster":{"title":"Hommes jouant au trictrac à la chandelle (d’après De Coster)","artist":"D’après Adam de Coster (gravé par Vorsterman)","date":"1619–1628","place":"Flandres","game":"Trictrac","medium":"Gravure au burin","size":"37,1 × 35,1 cm","credit":"","p":["Une estampe d’après un tableau du peintre flamand des scènes à la chandelle Adam de Coster, portant en bas « A. De Coster pi. » et « Vorsterman ». Selon le musée, deux hommes debout devant une table jouent au trictrac à la lueur d’une chandelle.","À gauche, un homme à la pipe regarde ; à droite, une jeune fille joue du luth et un homme en bonnet désigne la chandelle. Le joueur du premier plan, de dos, se penche sur la table, tandis que son adversaire tient la main au-dessus du jeu. Une seule chandelle éclaire la scène et ne fait ressortir que visages et mains."],"spots":[["Le tablier","Le jeu sur la table, à demi dans l’ombre."],["La chandelle","L’unique chandelle qui éclaire la scène."],["Le joueur de dos","Penché sur la table."],["L’adversaire","La main au-dessus du jeu."],["Le fumeur","Il regarde à gauche, la pipe à la bouche."],["La joueuse de luth","Une jeune fille au luth à droite."]]},"kiebitz":{"title":"Kiebitz (le spectateur)","artist":"Hans Watzek","date":"1894","place":"Sans doute Autriche","game":"Cartes","medium":"Similigravure (illustration de livre)","size":"10,0 × 12,1 cm","credit":"","p":["Une photographie de l’artiste photographe viennois Hans Watzek, signée « HANS WATZEK 94 » en haut à droite. Elle est reproduite en similigravure dans un livre dont le titre courant demande « La Photographie est-elle un Art ? ».","Le titre allemand « Kiebitz » désigne le vanneau, et en argot le spectateur qui se mêle d’une partie de cartes. Un homme coiffé d’un chapeau examine son jeu, tandis que celui de devant, à la longue pipe, regarde par-dessus. Le grain et le ton pictural sont typiques de la photographie artistique d’alors, qui voulait égaler la peinture."],"spots":[["Le jeu","Les cartes que l’homme de droite examine."],["Le joueur","En melon, la pipe à la bouche."],["Le spectateur","L’homme à la longue pipe, sans doute le « Kiebitz » du titre."],["La chope","Une chope en verre sur la table."],["La signature","« HANS WATZEK 94 » en haut à droite."],["La légende","« HANS WATZEK. — KIEBITZ. » en dessous."]]},"evdvelde":{"title":"Joueurs de trictrac dans le jardin d’un château","artist":"Esaias van de Velde","date":"1630","place":"Pays-Bas","game":"Trictrac","medium":"Pierre noire et lavis gris","size":"18,5 × 30,1 cm","credit":"","p":["Un dessin d’Esaias van de Velde (1587–1630), pionnier de la scène de genre et du paysage hollandais, signé « E.V.VELDE » en bas à droite. Selon le musée, une élégante compagnie joue au trictrac à une table dans le jardin d’un château.","Un homme penché sur le jeu et un homme assis se font face, des dames regardent derrière. Devant à gauche, un rafraîchissoir à vin et deux cruches ; plus loin, un garçon et un paon près d’une fontaine. Un gracieux après-midi de jeu en plein air."],"spots":[["Le tablier","Le trictrac sur la table."],["L’homme penché","Coiffé d’un chapeau, il se penche sur le jeu."],["L’homme assis","Jambes croisées, face au jeu."],["Les dames","Debout derrière, elles suivent la partie."],["Paon et garçon","Un paon et un garçon près de la fontaine."],["Le rafraîchissoir","Un rafraîchissoir et deux cruches devant à gauche."]]},"cooghen":{"title":"Deux hommes jouant au trictrac","artist":"Leendert van der Cooghen","date":"1666","place":"Pays-Bas (Haarlem)","game":"Trictrac","medium":"Eau-forte","size":"9,3 × 15,6 cm","credit":"","p":["Une eau-forte du peintre haarlemois Van der Cooghen, avec l’année « 1666 » griffée sur le mur au-dessus du jeu. Selon le musée, deux hommes jouent au trictrac à une table de taverne, tandis qu’une femme regarde par-dessus l’épaule de celui de gauche.","L’homme âgé, à gauche, porte un manteau bordé de fourrure et tient un grand verre ; le jeune homme, à droite, arbore un chapeau à plumes remarquable. Un petit singe est assis à la fenêtre. Le rebord et les flèches du tablier sont nettement dessinés."],"spots":[["Le tablier","Le trictrac sur la table."],["L’homme âgé","En manteau bordé de fourrure."],["Le verre","Le grand verre de l’homme âgé."],["La femme qui regarde","Par-dessus l’épaule de l’homme de gauche."],["Le singe","Un petit singe à la fenêtre."],["L’homme au chapeau à plumes","Le jeune joueur emplumé."]]},"roybet":{"title":"Le joueur d’échecs","artist":"Ferdinand Roybet","date":"1875","place":"France (Paris)","game":"Échecs","medium":"Sans doute eau-forte","size":"26,1 × 19,6 cm","credit":"","p":["Une estampe dessinée et gravée par le peintre français Roybet, amateur de cavaliers du XVIIe siècle (« F. Roybet del. et sc. » en bas à gauche). Dessous, le titre « LE JOUEUR D’ÉCHECS » et, à droite, le nom de l’éditeur Cadart.","Un homme en chapeau à plumes, l’épée au côté, est assis de biais sur un banc et tend la main vers les pièces. Aucun adversaire n’apparaît ; il semble méditer seul la position. Sur l’étagère derrière, une chope, un pichet et des verres."],"spots":[["Échiquier et pièces","L’échiquier et les pièces sur le banc."],["Le cavalier","L’homme au chapeau à plumes."],["La main tendue","Sa main vers une pièce."],["L’épée","Une longue épée au côté."],["La vaisselle","Chope, pichet et verres sur l’étagère."],["Le titre","« LE JOUEUR D’ÉCHECS »."]]},"capot":{"title":"« St. Pierre, mon ami, vous êtes capot ! » (peintre et modèle aux cartes)","artist":"Anonyme (édité par Aubert & Cie)","date":"1838","place":"France (Paris)","game":"Cartes (sans doute le piquet)","medium":"Lithographie","size":"30,5 × 22,2 cm","credit":"","p":["Une lithographie parue dans le journal satirique parisien Le Charivari le 9 septembre 1838, numéro 13 de la suite « Les Artistes ». La légende : « St. Pierre, mon ami, vous êtes capot ! »","Selon le musée, le peintre appelle son partenaire « saint Pierre » parce que l’homme pose pour le saint du tableau. Être « capot », c’est perdre toutes les levées au piquet : le jeu est donc sans doute le piquet."],"spots":[["Les cartes","Des cartes jouées sur la petite table."],["Le modèle","L’homme aux cheveux longs, de dos ; cheveux et barbe comme le saint peint, c’est sans doute le modèle."],["Le peintre","L’homme de droite, ses cartes en main, sans doute le peintre."],["Le tableau du saint","Le saint à demi peint sur le chevalet."],["Le tabouret","Le tabouret de bois du modèle."],["La légende","« St. Pierre, mon ami, vous êtes capot ! »"]]},"ziacard":{"title":"Roi de trèfle (Antonio Salva, gouverneur du pueblo de Zia)","artist":"Adam Clark Vroman (photographie), Lazarus & Melzer (éditeur)","date":"1900","place":"États-Unis (Los Angeles)","game":"Cartes à jouer","medium":"Autotypie (similigravure)","size":"8,8 × 6,3 cm","credit":"","p":["Selon la notice du musée, c’est une carte d’un jeu en boîte de 53 cartes, joker compris, imprimé en similigravure avec des photographies d’Amérindiens. Les photos sont d’Adam Clark Vroman ; l’éditeur était Lazarus & Melzer, à Los Angeles.","Au lieu d’un roi dessiné, le roi de trèfle porte le portrait d’Antonio Salva, gouverneur du pueblo de Zia au Nouveau-Mexique. Son nom et son titre sont imprimés en bas, avec le K et le trèfle dans les coins. Il s’agissait sans doute d’un souvenir pour les visiteurs de l’Ouest."],"spots":[["L’index du coin","K et trèfle en haut à gauche, comme sur tout jeu."],["Le visage du gouverneur","Antonio Salva, regardant de côté."],["Les cheveux longs","Cheveux aux épaules et frange droite."],["Le foulard","Un linge noué au col d’une chemise blanche."],["Nom et titre","Imprimé : « Antonio Salva. Governor Pueblo of Sia »."],["L’index inversé","K et trèfle à l’envers, en bas à droite."]]},"gothink":{"title":"Partie de go","artist":"Photographe japonais (anonyme)","date":"1887-1897","place":"Japon","game":"Go","medium":"Photographie coloriée à la main (illustration de livre)","size":"8,8 × 13 cm","credit":"","p":["Prise par un photographe japonais anonyme et coloriée à la main au Japon, cette photographie est collée page 65 d’un livre en anglais sur le Japon. La légende imprimée explique : « Le go est un jeu plus difficile que les échecs. Il fut introduit de Chine au Japon au VIIIe siècle. »","De part et d’autre d’un goban à pieds, la femme de gauche pose une pierre tandis qu’un vieil homme à barbe blanche, la main sur la tête, réfléchit. La femme du milieu regarde le jeu ; devant, un plateau de douceurs et des bols de thé. La scène a sans doute été mise en place en studio pour les visiteurs étrangers."],"spots":[["Le goban","Un goban à pieds, garni de pierres."],["La main qui joue","La femme de gauche tend la main."],["Le vieil homme perplexe","Barbe blanche, la main sur la tête."],["La femme qui regarde","En kimono rayé, au milieu."],["Le plateau de douceurs","Des friandises sur un plateau, devant."],["Le bol de pierres","Un bol à couvercle près du goban."]]},"craps":{"title":"Jeunes joueurs","artist":"Francis A. Place","date":"1888-1893","place":"Probablement les États-Unis","game":"Dés","medium":"Photographie (illustration de livre)","size":"14 × 9,9 cm","credit":"","p":["Selon la notice du musée, quatre garçons non identifiés jouent aux dés ; le nom du photographe Francis A. Place figure sur le support. L’image est collée deux pages avant la page 142 d’un livre, avec les mentions imprimées « tirages sur papier américain “Aristo” » et « faite avec l’appareil à éclair Williams ». Elle servait sans doute d’échantillon pour le papier et le flash.","Contre un mur, de la paille au sol, les garçons entourent une caisse. Dessus, une assiette en fer-blanc et deux dés. Celui de droite claque des doigts ; celui assis par terre, le menton dans la main, fixe le jeu. En bas est gravé « COME SEV », sans doute le cri « viens, sept ! » du craps, le jeu de dés américain."],"spots":[["Deux dés","Deux dés sur la caisse."],["L’assiette en fer-blanc","Une assiette sur la caisse, sans doute pour la mise."],["Le claquement de doigts","Le garçon de droite claque des doigts vers les dés."],["Le garçon assis","Par terre, le menton dans la main."],["« COME SEV »","Lettres gravées en bas : sans doute « viens, sept ! »."],["Les lettres de la caisse","Lettres au pochoir sur le flanc de la caisse."]]},"bikkel":{"title":"Étude d’un homme jouant aux osselets","artist":"Jan Baptist Weenix (peut-être)","date":"1642–1647","place":"Italie (Rome)","game":"Osselets","medium":"Pierre noire et craie blanche sur papier bleu","size":"26,7 × 18,0 cm","credit":"","p":["Un dessin à la pierre noire et à la craie blanche sur papier bleu. Selon le musée, il est peut-être du peintre hollandais Weenix, de ses années romaines ; il fut autrefois vendu comme une œuvre d’Anthonie Palamedesz.","Un homme en chapeau se penche très bas, les yeux sur ses mains ; quelques petits os gisent au sol à ses pieds. Lancer et rattraper des astragales de mouton est un jeu très ancien, souvent présenté comme l’ancêtre des dés."],"spots":[["Le visage","Il regarde ses mains sous le chapeau."],["Les mains","Sans doute prêtes à lancer les osselets."],["Les os au sol","De petits os par terre."],["La chaussure","Le pied bien campé."],["La craie blanche","Les lumières à la craie blanche."],["Le manteau","Le manteau sur son dos."]]},"stukken":{"title":"Projet de pièces d’échecs","artist":"Anonyme (France)","date":"1850–1875","place":"France","game":"Échecs","medium":"Plume et encre noire, gouache blanche et rouge orangé sur esquisse à la pierre noire, papier bleu","size":"26,5 × 20,0 cm","credit":"","p":["Un dessin de projet pour un jeu d’échecs, par un dessinateur français inconnu. Deux rangées montrent chacune cinq sortes de pièces : roi, dame, tour, une figure et cavalier.","En haut, un roi et une dame couronnés et un soldat agenouillé tenant une lance ; en bas, un roi enturbanné, une dame voilée et un archer agenouillé : les deux camps étaient sans doute pensés comme des armées d’Occident et d’Orient. Le blanc et le rouge orangé suggèrent la sculpture et le brillant."],"spots":[["Roi (haut)","Couronné, sceptre en main."],["Dame (haut)","La dame couronnée."],["La tour","La tour du jeu."],["Le lancier","Pièce agenouillée avec une lance."],["Le roi enturbanné","Le roi de la rangée du bas."],["L’archer","Pièce agenouillée bandant son arc."]]},"rozetempel":{"title":"Jardin fleuri, ou l’agréable Temple des roses (plateau de jeu de dés)","artist":"Anonyme (édité par Hendrik Moolenyzer)","date":"1792–1847","place":"Pays-Bas (Amsterdam)","game":"Plateau de jeu de dés","medium":"Estampe","size":"46,1 × 39,6 cm","credit":"","p":["Un plateau de jeu sur feuille volante publié par l’éditeur amstellodamois Moolenyzer, intitulé en haut « BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL » (Jardin fleuri, ou l’agréable Temple des roses).","Au centre, un vase de roses dans le « ROZE TEMPEL », entouré de paires de dés et de fleurs. On y jouait sans doute en lançant deux dés et en payant ou touchant la mise sur la fleur correspondant au coup."],"spots":[["Le titre","« BLOEMENHOF of VERMAKELIJKE ROZE TEMPEL »."],["Le temple","Le « ROZE TEMPEL » au centre."],["Paires de dés","Combinaisons de deux dés."],["Le vase","Des roses dans un vase au temple."],["La tulipe","Une des fleurs du cercle."],["L’éditeur","« Te AMSTERDAM bij H. Moolenyzer »."]]},"brelan":{"title":"Le Brelan (des Jeux et plaisirs de l’enfance)","artist":"Claudine Stella (d’après Jacques Stella)","date":"1657","place":"France (Paris)","game":"Brelan (jeu de trois cartes)","medium":"Gravure au burin","size":"12,0 × 14,2 cm","credit":"","p":["Une planche des Jeux et plaisirs de l’enfance, recueil de 51 scènes de jeux d’enfants. Au-dessus des vers, « LE BRELAN » : des enfants potelés jouent aux cartes assis par terre.","Les vers racontent que l’un roule son cerceau, que les autres en un monceau tentent la fortune aux cartes, et que tel qui croyait gagner s’en va plus léger. Le brelan est souvent cité parmi les lointains ancêtres du poker."],"spots":[["Un jeu en main","Un enfant déploie ses cartes."],["Une carte au sol","Une carte marquée « A » par terre."],["Le curieux","Un enfant regarde le jeu par-derrière."],["Le cerceau","Un enfant pousse un cerceau avec un bâton."],["La tour","Une tour ronde au fond."],["Le titre","« LE BRELAN » et les vers."]]},"pwkarte":{"title":"Carte à jouer ronde aux six perroquets","artist":"Maître PW de Cologne","date":"1470–1500","place":"Allemagne (Cologne)","game":"Cartes à jouer (jeu rond)","medium":"Gravure au burin","size":"Diamètre 7,0 cm","credit":"","p":["Une carte à jouer ronde imprimée au burin il y a plus de cinq cents ans. Selon le musée, elle appartient à un jeu de 70 cartes rondes en cinq couleurs : roses, ancolies, œillets, perroquets et lièvres.","Chaque couleur comptait dix cartes numérotées de 1 à 10 et quatre cartes à figure. Voici le six de perroquets, avec un « 6 » arabe en haut et un « VI » romain en bas ; six perroquets entourent l’ornement central."],"spots":[["Le « 6 »","Le chiffre arabe en haut."],["Le « VI »","Le chiffre romain en bas."],["Le perroquet du haut","Un perroquet comme perché."],["Le perroquet qui bat des ailes","Ailes déployées."],["Le perroquet renversé","La tête en bas."],["L’ornement central","L’ornement rayonnant au centre."]]},"nilson":{"title":"Le jeu de tablier (dames et tocadille)","artist":"Johann Esaias Nilson","date":"1731–1788","place":"Allemagne (Augsbourg)","game":"Dames et tocadille","medium":"Eau-forte et burin","size":"18,9 × 28,8 cm","credit":"","p":["Une estampe à cadre rocaille dessinée et éditée par le graveur augsbourgeois Nilson, intitulée en haut « Das Bretspiel » (Le jeu de tablier). C’est la troisième d’une suite de quatre.","Selon le musée, à la table de gauche un homme et une femme jouent aux dames, tandis qu’à droite deux hommes jouent au tocadille, un jeu de la famille du trictrac. Le vers allemand dit que qui joue au tocadille veut ardemment gagner, et que qui joue aux dames a besoin de tous ses sens."],"spots":[["Le damier","Sur la table de gauche."],["Le tablier de tocadille","Sur la petite table de droite."],["Le liseur","Un homme lit une lettre, la pipe aux lèvres."],["La femme à la vaisselle","Elle porte des plats à droite."],["Le parc","Le parc au-delà du cadre."],["Le vers","« Wer Tocadille spielt… »."]]}};
